import bisect
import statistics

INF = 1e9


def _norm(inp):
    evs = []
    raw = inp.get("events") or []
    for k, e in enumerate(raw):
        if not isinstance(e, dict):
            continue
        try:
            t = int(e.get("t") or 0)
        except Exception:
            t = 0
        idx = e.get("i", k)
        off = e.get("off")
        ln = e.get("len")
        off = off if isinstance(off, int) else None
        ln = ln if isinstance(ln, int) else None
        sid = e.get("sid")
        sid = str(sid) if sid is not None else None
        evs.append({"i": idx, "t": t, "node": str(e.get("node")), "type": str(e.get("type")),
                    "off": off, "len": ln, "sid": sid, "k": k})
    evs.sort(key=lambda e: (e["t"], e["k"]))
    return evs


def _fp(e):
    return (e["node"], e["type"], e["off"], e["len"])


def _estimate_jitter(evs):
    ts = [e["t"] for e in evs]
    gaps = sorted(b - a for a, b in zip(ts, ts[1:]) if b > a)
    med = statistics.median(gaps) if gaps else 1
    return max(4.0 * med, 2.0)


def solve(state, params):
    inp = state.get("input") or {}
    evs = _norm(inp)
    n = len(evs)
    J = _estimate_jitter(evs)
    W = 10

    S = {}

    def mk(sid):
        if sid not in S:
            S[sid] = {"st": "pending", "node": None, "off": 0, "dur": 0, "pre": 0,
                      "cn": None, "ct": -INF, "last": -INF, "fp": {}, "end": None}
        return S[sid]

    lab = {}
    for p, e in enumerate(evs):
        if e["sid"] is not None and e["type"] != "crash":
            mk(e["sid"])
            lab.setdefault(e["sid"], []).append(p)

    done = [False] * n
    assign = {}

    def next_lab(sid, p):
        lst = lab.get(sid, [])
        j = bisect.bisect_right(lst, p)
        while j < len(lst) and done[lst[j]]:
            j += 1
        return evs[lst[j]] if j < len(lst) else None

    def base_eval(x, e):
        st = x["st"]
        typ = e["type"]
        off = e["off"]
        opts = []
        if _fp(e) in x["fp"]:
            opts.append((0.4, "dup"))
        if st == "pending":
            return opts
        if st in ("committed", "aborted"):
            if e["t"] - (x["end"] or 0) <= 2 * J and typ in ("write", "checkpoint") and off is not None \
                    and off <= x["off"] and e["node"] == x["node"]:
                opts.append((2.5, "late"))
            return opts
        if typ == "abort":
            if st == "active":
                opts.append((0.5 if x["node"] == e["node"] else 6.0, "exact"))
            else:
                if x["cn"] == e["node"] and e["t"] - x["ct"] <= J:
                    opts.append((0.8, "precrash"))
                opts.append((2.5, "irec"))
            return opts
        if off is None:
            return opts
        if typ == "recover":
            if st == "down":
                if off == x["dur"]:
                    opts.append((0.0, "exact"))
                elif off == x["pre"] and off > x["dur"]:
                    opts.append((1.0, "exact"))
                elif off > x["dur"]:
                    opts.append((1.8, "exact"))
                else:
                    opts.append((4.5, "exact"))
            else:
                if e["t"] - x["last"] <= J and off == x["dur"]:
                    opts.append((3.5, "early"))
                elif off <= x["off"] and off >= x["dur"] and e["t"] - x["last"] <= J:
                    opts.append((4.5, "early"))
            return opts
        if st == "active":
            nodepen = 0.0 if x["node"] == e["node"] else 6.0
            if off == x["off"]:
                opts.append((0.0 + nodepen, "exact"))
            elif off > x["off"]:
                opts.append((1.5 + nodepen, "gap"))
            else:
                end = off + (e["len"] or 0)
                if typ != "commit" and end <= x["off"] and off >= x["dur"]:
                    opts.append((1.2 + nodepen, "late"))
                elif typ != "commit" and end <= x["off"]:
                    opts.append((2.8 + nodepen, "late"))
                else:
                    opts.append((5.0 + nodepen, "gap"))
        elif st == "down":
            if x["cn"] == e["node"] and off == x["pre"] and e["t"] - x["ct"] <= 2 * J:
                opts.append((0.3, "precrash"))
            elif x["cn"] == e["node"] and off < x["pre"] and e["t"] - x["ct"] <= 2 * J and typ != "commit":
                opts.append((1.5, "prelate"))
            if off == x["dur"]:
                opts.append((1.8, "irec"))
            elif off > x["dur"]:
                opts.append((3.2, "irec"))
        return opts

    def predicted(x, e, kind):
        typ = e["type"]
        if kind in ("exact", "gap", "irec"):
            if typ == "write":
                return e["node"], e["off"] + (e["len"] or 0)
            if typ in ("checkpoint", "commit", "recover"):
                return e["node"], e["off"]
            return e["node"], x["off"]
        return x["node"], x["off"]

    def future_adj(sid, x, e, kind, p):
        g = next_lab(sid, p)
        typ = e["type"]
        adj = 1e-6 * max(0.0, e["t"] - x["last"])
        if typ == "abort":
            if g is not None and g["type"] != "abort" and g["t"] - e["t"] > 0.5 * J:
                if _fp(g) not in x["fp"]:
                    adj += 10.0
            if x["st"] == "active":
                for q in range(p + 1, min(n, p + W + 1)):
                    f = evs[q]
                    if done[q] or f["sid"] is not None:
                        continue
                    if f["type"] in ("write", "checkpoint", "commit") and f["node"] == x["node"] \
                            and f["off"] == x["off"]:
                        adj += 1.0
                        break
            return adj
        if g is None:
            return adj
        if typ == "recover":
            if g["node"] == e["node"]:
                adj -= 0.4
            elif g["type"] != "recover":
                adj += 1.5
            if g["off"] is not None and g["off"] == e["off"]:
                adj -= 0.2
            return adj
        if kind in ("dup", "late", "prelate", "precrash", "early"):
            return adj
        nn, no = predicted(x, e, kind)
        if g["type"] in ("write", "checkpoint", "commit") and g["off"] is not None:
            if _fp(g) == _fp(e):
                adj -= 0.3
            elif g["node"] == nn and g["off"] == no:
                adj -= 0.35
            elif g["node"] == nn and g["off"] > no:
                adj += 0.0
            elif g["off"] < no:
                end = g["off"] + (g["len"] or 0)
                if g["t"] - e["t"] <= J and end <= no:
                    adj += 0.2
                else:
                    adj += 0.7
            elif g["node"] != nn:
                adj += 0.3
        return adj

    def apply(sid, e, kind):
        x = S[sid]
        typ = e["type"]
        off = e["off"]
        x["fp"][_fp(e)] = e["t"]
        x["last"] = max(x["last"], e["t"])
        if typ == "open":
            if x["st"] == "pending":
                x.update(st="active", node=e["node"], off=0, dur=0)
            return
        if kind == "dup":
            return
        if kind == "late":
            if typ == "checkpoint" and off is not None and off <= x["off"]:
                x["dur"] = max(x["dur"], off)
            return
        if kind == "prelate":
            if typ == "checkpoint" and off is not None:
                x["dur"] = max(x["dur"], off)
                x["off"] = x["dur"]
            return
        if kind == "precrash":
            if typ == "write":
                x["pre"] = off + (e["len"] or 0)
            elif typ == "checkpoint":
                x["pre"] = off
                x["dur"] = max(x["dur"], off)
                x["off"] = x["dur"]
            elif typ == "commit":
                x.update(st="committed", off=off, dur=off, end=e["t"])
            elif typ == "abort":
                x.update(st="aborted", end=e["t"])
            return
        if kind == "early":
            x["node"] = e["node"]
            if off is not None:
                x["off"] = off
                x["dur"] = off
            x["early"] = True
            return
        if typ == "write":
            if off is not None:
                x["off"] = off + (e["len"] or 0)
            x["st"] = "active"
            x["node"] = e["node"]
        elif typ == "checkpoint":
            if off is not None:
                x["off"] = off
                x["dur"] = off
            x["st"] = "active"
            x["node"] = e["node"]
        elif typ == "commit":
            if off is not None:
                x["off"] = off
                x["dur"] = off
            x.update(st="committed", node=e["node"], end=e["t"])
        elif typ == "abort":
            x.update(st="aborted", end=e["t"])
        elif typ == "recover":
            if off is not None:
                x["off"] = off
                x["dur"] = off
            x.update(st="active", node=e["node"])

    def best_option(sid, e, p):
        x = S[sid]
        best = (INF, None)
        for c, kd in base_eval(x, e):
            if c >= INF:
                continue
            c2 = c + future_adj(sid, x, e, kd, p)
            if c2 < best[0]:
                best = (c2, kd)
        return best

    def is_exact(e):
        if e["sid"] is not None:
            x = S.get(e["sid"])
            if x is None:
                return True
            return any(c == 0.0 and kd == "exact" for c, kd in base_eval(x, e))
        for sid, x in S.items():
            if x["st"] == "active" and any(c == 0.0 and kd == "exact" for c, kd in base_eval(x, e)):
                return True
        return False

    def find_prereq(p):
        e = evs[p]
        if e["type"] not in ("write", "checkpoint", "commit") or e["off"] is None:
            return None
        if is_exact(e):
            return None
        if e["sid"] is not None:
            cands = [e["sid"]]
        else:
            cands = [s for s in sorted(S) if S[s]["st"] == "active" and S[s]["node"] == e["node"]]
        for sid in cands:
            x = S.get(sid)
            if x is None or x["st"] != "active" or x["off"] >= e["off"]:
                continue
            for q in range(p + 1, min(n, p + W + 1)):
                f = evs[q]
                if done[q] or f["type"] != "write" or f["off"] is None:
                    continue
                if f["t"] - e["t"] > 2 * J:
                    break
                if f["sid"] is not None and f["sid"] != sid:
                    continue
                if f["node"] != x["node"] or f["off"] != x["off"]:
                    continue
                if f["off"] + (f["len"] or 0) <= e["off"]:
                    return (q, sid)
        return None

    def process(p, forced_sid=None):
        e = evs[p]
        done[p] = True
        typ = e["type"]
        if typ == "crash":
            for sid in sorted(S):
                x = S[sid]
                if x["st"] == "active" and x["node"] == e["node"]:
                    if x.pop("early", False):
                        continue
                    x["st"] = "down"
                    x["pre"] = x["off"]
                    x["cn"] = e["node"]
                    x["ct"] = e["t"]
                    x["off"] = x["dur"]
            return
        sid = e["sid"] or forced_sid
        if sid is not None:
            mk(sid)
            if typ == "open":
                apply(sid, e, "exact")
            else:
                c, kd = best_option(sid, e, p)
                apply(sid, e, kd or "exact")
            if e["sid"] is None:
                assign[e["i"]] = sid
            return
        best = (INF, None, None)
        for s in sorted(S):
            c, kd = best_option(s, e, p)
            if c < best[0]:
                best = (c, s, kd)
        if best[1] is None:
            pool = [s for s in sorted(S) if S[s]["st"] != "pending" and S[s]["node"] == e["node"]] or \
                   [s for s in sorted(S) if S[s]["st"] != "pending"] or sorted(S)
            if not pool:
                return
            s = min(pool, key=lambda s: -S[s]["last"])
            assign[e["i"]] = s
            apply(s, e, "late")
            return
        assign[e["i"]] = best[1]
        apply(best[1], e, best[2])

    p = 0
    guard = 0
    while p < n:
        if done[p]:
            p += 1
            continue
        guard += 1
        if guard > 4 * n + 10:
            process(p)
            p += 1
            continue
        pr = find_prereq(p)
        if pr is not None:
            process(pr[0], pr[1])
            continue
        process(p)
        p += 1

    sessions = {}
    for sid, x in S.items():
        st = x["st"]
        if st == "pending":
            st = "active"
        dur = x["off"] if st == "committed" else x["dur"]
        sessions[sid] = {"status": st, "durable": int(dur)}
    for e in evs:
        if e["type"] != "crash" and e["sid"] is None and e["i"] not in assign:
            if sessions:
                assign[e["i"]] = sorted(sessions)[0]
    state["output"] = {"assignments": {str(k): v for k, v in assign.items()}, "sessions": sessions}
    return state

import time
from bisect import bisect_right


def _estimate_jitter(evs):
    ts = [e["t"] for e in evs]
    gaps = sorted(ts[k + 1] - ts[k] for k in range(len(ts) - 1)) or [1]
    med = max(1, gaps[len(gaps) // 2])
    cap = max(10, 6 * med)
    by_sid = {}
    for p, e in enumerate(evs):
        if e["sid"] is not None and e["type"] == "write" and e["off"] is not None:
            by_sid.setdefault(e["sid"], []).append(p)
    inv = 0
    for ps in by_sid.values():
        for x in range(len(ps)):
            a = evs[ps[x]]
            for y in range(x + 1, min(len(ps), x + 10)):
                b = evs[ps[y]]
                if b["node"] == a["node"] and b["off"] + (b["len"] or 0) == a["off"]:
                    d = b["t"] - a["t"]
                    if d <= cap and d > inv:
                        inv = d
    return max(3, inv + 1)


def solve(state, params):
    t0 = time.process_time()
    inp = state.get("input") or {}
    raw = list(inp.get("events") or [])
    evs = []
    for e in raw:
        try:
            ty = e.get("type")
            off = e.get("off")
            ln = e.get("len")
            evs.append({"i": int(e.get("i")), "t": int(e.get("t") or 0), "node": e.get("node"),
                        "type": ty, "off": (int(off) if off is not None else None),
                        "len": (int(ln) if ln is not None else (0 if ty == "write" else None)),
                        "sid": e.get("sid")})
        except Exception:
            continue
    evs.sort(key=lambda e: (e["t"], e["i"]))
    n_ev = len(evs)
    J = _estimate_jitter(evs) if n_ev > 1 else 3

    lab_pos = {}
    for p, e in enumerate(evs):
        if e["sid"] is not None and e["type"] != "crash":
            lab_pos.setdefault(e["sid"], []).append(p)
    sids = []
    seen = set()
    for e in evs:
        if e["type"] == "open" and e["sid"] is not None and e["sid"] not in seen:
            sids.append(e["sid"]); seen.add(e["sid"])
    for e in evs:
        if e["sid"] is not None and e["type"] != "crash" and e["sid"] not in seen:
            sids.append(e["sid"]); seen.add(e["sid"])

    S = {}
    assign = {}
    dup_of = {}
    fp_index = {}
    dup_used = set()
    hint = {}
    fast = [False]
    pending = []

    def fp(e):
        return (e["node"], e["type"], e["off"], e["len"])

    def next_labelled(sid, p):
        lst = lab_pos.get(sid)
        if not lst:
            return None
        k = bisect_right(lst, p)
        if k < len(lst):
            return evs[lst[k]]
        return None

    def new_off(e):
        if e["type"] == "write":
            return e["off"] + (e["len"] or 0)
        return e["off"]

    def cand_cost(s, e):
        ty = e["type"]
        st = s["status"]
        n = e["node"]
        off = e["off"]
        if ty == "write":
            if off is None:
                return None
            if st == "active":
                if s["node"] != n:
                    return None
                d = off - s["off"]
                if d == 0:
                    return (0.0, "fresh")
                if d > 0:
                    return (2.0, "fresh")
                return (8.0, "stale")
            if st == "down":
                if s["cnode"] == n and off == s["pre"] and e["t"] - s["ct"] <= J:
                    return (0.5, "late")
                if off == s["dur"]:
                    return (3.0, "implicit")
                if s["dur"] < off <= s["pre"]:
                    return (4.0, "implicit")
            return None
        if ty in ("checkpoint", "commit"):
            if off is None:
                return None
            if st == "active":
                if s["node"] != n:
                    return None
                d = off - s["off"]
                if d == 0:
                    return (0.0, "fresh")
                if d > 0:
                    return (2.0, "fresh")
                if ty == "checkpoint" and off >= s["dur"]:
                    return (1.5 if e["t"] - s["lt"] <= J else 5.0, "stalecp")
                return (6.0, "fresh")
            if st == "down":
                if s["cnode"] == n and s["dur"] <= off <= s["pre"] and e["t"] - s["ct"] <= J:
                    return (0.5 if off == s["pre"] else 1.5, "late")
                if off == s["dur"]:
                    return (5.0, "implicit")
                if s["dur"] < off <= s["pre"]:
                    return (5.5, "implicit")
            return None
        if ty == "recover":
            if off is None:
                return None
            if st == "down":
                if off == s["dur"]:
                    return (0.0, "recover")
                if s["dur"] < off <= s["pre"]:
                    return (1.0, "recover")
                return (5.0, "recover")
            if st == "active":
                return (6.0 if off == s["dur"] else 9.0, "recover")
            return None
        if ty == "abort":
            if st == "active" and s["node"] == n:
                return (1.0, "abort")
            if st == "down" and s["cnode"] == n and e["t"] - s["ct"] <= J:
                return (1.5, "abort")
            return None
        return None

    def lookahead(s, e, p):
        ty = e["type"]
        sid = s["sid"]
        nl = next_labelled(sid, p)
        if ty == "abort":
            pen = 0.0
            if nl is not None and nl["t"] > e["t"] + J and nl["type"] != "abort":
                pen += 5.0
            if s["status"] == "active":
                q = p + 1
                lim = e["t"] + 4 * J
                while q < n_ev and evs[q]["t"] <= lim:
                    f = evs[q]
                    if (f["node"] == s["node"] and f["type"] in ("write", "checkpoint", "commit")
                            and f["off"] == s["off"] and (f["sid"] is None or f["sid"] == sid)):
                        pen += 0.6
                        break
                    q += 1
            return pen
        if nl is None:
            if ty in ("write", "checkpoint") and s["status"] == "active":
                return 0.05
            return 0.0
        if nl["type"] == "open":
            return 0.0
        if ty == "commit":
            if nl["type"] == "commit" and nl["off"] == e["off"]:
                return -0.4
            if nl["t"] > e["t"] + J:
                return 0.6
            return 0.0
        no = new_off(e)
        b = 0.0
        if nl["type"] in ("write", "checkpoint", "commit") and nl["off"] is not None:
            if nl["off"] == no and nl["node"] == e["node"]:
                b -= 0.4
            elif nl["off"] < no and nl["t"] - e["t"] <= 3 * J and nl["node"] == e["node"]:
                b += 0.5
            if nl["node"] != e["node"] and ty != "recover" and s["status"] != "down":
                b += 0.3
        elif nl["type"] == "recover" and ty == "recover":
            b += 0.3
        return b

    def apply(s, e, mode):
        ty = e["type"]
        off = e["off"]
        if e["t"] > s["lt"]:
            s["lt"] = e["t"]
        if mode == "late":
            if ty == "write":
                s["pre"] = off + (e["len"] or 0)
            elif ty == "checkpoint":
                s["dur"] = max(s["dur"], off)
                s["off"] = s["dur"]
            elif ty == "commit":
                s["dur"] = off
                s["off"] = off
                s["status"] = "committed"
            return
        if mode == "abort":
            s["status"] = "aborted"
            s["off"] = s["dur"]
            return
        if mode == "stale":
            return
        if mode == "stalecp":
            s["dur"] = max(s["dur"], off)
            return
        if mode == "recover":
            s["status"] = "active"
            s["node"] = e["node"]
            s["off"] = off
            s["dur"] = off
            return
        if mode == "implicit":
            s["status"] = "active"
            s["node"] = e["node"]
            s["dur"] = max(s["dur"], min(off, s["pre"]))
            s["off"] = off
        if mode == "force":
            if ty == "abort":
                s["status"] = "aborted"
                s["off"] = s["dur"]
                return
            if ty == "recover":
                if off is not None:
                    s["status"] = "active"; s["node"] = e["node"]; s["off"] = off; s["dur"] = off
                return
            if off is None:
                return
            if ty in ("write", "checkpoint", "commit"):
                s["node"] = e["node"]
                if s["status"] == "down":
                    s["status"] = "active"
        if off is None:
            return
        if ty == "write":
            s["off"] = off + (e["len"] or 0)
        elif ty == "checkpoint":
            s["off"] = off
            s["dur"] = off
        elif ty == "commit":
            s["off"] = off
            s["dur"] = off
            s["status"] = "committed"

    def record(p, sid):
        e = evs[p]
        assign[e["i"]] = sid
        fp_index.setdefault(fp(e), []).append(p)

    def find_dup(p):
        lst = fp_index.get(fp(evs[p]))
        if not lst:
            return None
        for q in reversed(lst):
            if q in dup_used or q == p:
                continue
            return q
        return None

    def mark_dup(p, q, sid):
        dup_used.add(q)
        assign[evs[p]["i"]] = sid
        dup_of[evs[p]["i"]] = evs[q]["i"]

    def try_assign(p, force):
        e = evs[p]
        sid = e["sid"]
        if sid is None and p in hint:
            sid = hint[p]
        if sid is not None:
            s = S.get(sid)
            if s is None:
                if force:
                    record(p, sid)
                    return True
                return False
            c = cand_cost(s, e)
            q = find_dup(p)
            if (q is not None and assign.get(evs[q]["i"]) == sid
                    and not (c is not None and c[0] == 0 and e["type"] in ("write", "checkpoint"))):
                mark_dup(p, q, sid)
                return True
            if c is not None and (c[0] == 0 or force):
                apply(s, e, c[1])
                record(p, sid)
                return True
            if force:
                apply(s, e, "force")
                record(p, sid)
                return True
            return False
        best = None
        for s in S.values():
            c = cand_cost(s, e)
            if c is None:
                continue
            tot = c[0] + lookahead(s, e, p)
            key = (tot, c[0], s["lt"], s["order"])
            if best is None or key < best[0]:
                best = (key, s, c[1], c[0])
        q = find_dup(p)
        if q is not None and evs[q]["i"] in assign:
            dsid = assign[evs[q]["i"]]
            ty = e["type"]
            if ty == "write":
                use_dup = not (best is not None and best[3] == 0 and best[1]["sid"] == dsid)
            elif ty == "abort":
                use_dup = best is None or best[0][0] >= 1.5
            else:
                use_dup = best is None or best[3] > 0
            if use_dup:
                mark_dup(p, q, dsid)
                return True
        if best is None:
            if not force:
                return False
            fb = None
            for s in S.values():
                k = (0 if s["node"] == e["node"] else 1, -s["lt"], s["order"])
                if fb is None or k < fb[0]:
                    fb = (k, s)
            if fb is not None:
                record(p, fb[1]["sid"])
            elif sids:
                record(p, sids[0])
            return True
        if best[3] == 0 or force or best[0][0] <= 0:
            apply(best[1], e, best[2])
            record(p, best[1]["sid"])
            return True
        return False

    def retry():
        progress = True
        while progress and pending:
            progress = False
            for k in range(len(pending)):
                p = pending[k]
                if try_assign(p, False):
                    pending.pop(k)
                    progress = True
                    break

    def force_one(p):
        try_assign(p, True)
        retry()

    def expire(tnow):
        while pending:
            pending.sort(key=lambda x: (evs[x]["t"], evs[x]["i"]))
            p = pending[0]
            if evs[p]["t"] >= tnow - J:
                break
            pending.pop(0)
            force_one(p)

    order = 0
    for p, e in enumerate(evs):
        if not fast[0] and time.process_time() - t0 > 0.55:
            fast[0] = True
            while pending:
                pending.sort(key=lambda x: (evs[x]["t"], evs[x]["i"]))
                force_one(pending.pop(0))
        expire(e["t"])
        ty = e["type"]
        if ty == "crash":
            while True:
                cand = [q for q in pending if evs[q]["node"] == e["node"]]
                if not cand:
                    break
                cand.sort(key=lambda x: (evs[x]["t"], evs[x]["i"]))
                q = cand[0]
                pending.remove(q)
                force_one(q)
            for s in S.values():
                if s["status"] == "active" and s["node"] == e["node"]:
                    s["status"] = "down"
                    s["pre"] = s["off"]
                    s["off"] = s["dur"]
                    s["ct"] = e["t"]
                    s["cnode"] = e["node"]
            retry()
            continue
        if ty == "open":
            if e["sid"] is not None and e["sid"] not in S:
                S[e["sid"]] = {"sid": e["sid"], "node": e["node"], "off": 0, "dur": 0, "status": "active",
                               "pre": 0, "ct": -10 ** 9, "cnode": None, "lt": e["t"], "order": order}
                order += 1
                assign[e["i"]] = e["sid"]
                retry()
            elif e["sid"] is not None:
                assign[e["i"]] = e["sid"]
            else:
                pending.append(p)
            continue
        if e["sid"] is not None and not fp_index.get(fp(e)):
            for q in pending:
                if evs[q]["sid"] is None and q not in hint and fp(evs[q]) == fp(e):
                    s = S.get(e["sid"])
                    if s is not None and cand_cost(s, evs[q]) is not None:
                        hint[q] = e["sid"]
                    break
        if fast[0]:
            force_one(p)
            continue
        if try_assign(p, False):
            retry()
        else:
            pending.append(p)
    while pending:
        pending.sort(key=lambda x: (evs[x]["t"], evs[x]["i"]))
        force_one(pending.pop(0))

    out_as = {}
    for e in raw:
        try:
            if e.get("type") == "crash" or e.get("sid") is not None:
                continue
            i = int(e.get("i"))
        except Exception:
            continue
        sid = assign.get(i)
        cur = i
        k = 0
        while cur in dup_of and k < 10:
            cur = dup_of[cur]
            k += 1
            if cur in assign:
                sid = assign[cur]
        if sid is None:
            sid = sids[0] if sids else "s0"
        out_as[str(i)] = sid
    sess = {}
    for sid in sids:
        s = S.get(sid)
        if s is None:
            sess[sid] = {"status": "active", "durable": 0}
        else:
            sess[sid] = {"status": s["status"], "durable": int(s["dur"])}
    state["output"] = {"assignments": out_as, "sessions": sess}
    return state

import time
import heapq
import statistics

NEW, ACT, DOWN, COMM, ABOR = 0, 1, 2, 3, 4
STNAME = {NEW: "active", ACT: "active", DOWN: "down", COMM: "committed", ABOR: "aborted"}
GAP = 3.0
REC_MISS = 3.5
JIT = 1.2
DUP = 1.5
LATE = 1.8
ABORT_C = 0.3
CROSS = 25.0
IMPOSS = 12.0
SPARE = 1.5


def prepare(state, params):
    inp = state.get("input") or {}
    raw = inp.get("events") or []
    evs = []
    for k, e in enumerate(raw):
        try:
            i = int(e.get("i", k))
        except Exception:
            i = k
        t = e.get("t")
        try:
            t = int(t)
        except Exception:
            t = 0
        off = e.get("off")
        ln = e.get("len")
        try:
            off = int(off) if off is not None else None
        except Exception:
            off = None
        try:
            ln = int(ln) if ln is not None else None
        except Exception:
            ln = None
        evs.append([i, t, str(e.get("node")), str(e.get("type")), off, ln, e.get("sid"), k])
    sids = []
    seen = set()
    for e in evs:
        if e[3] == "open" and e[6] is not None and e[6] not in seen:
            seen.add(e[6]); sids.append(e[6])
    for e in evs:
        if e[6] is not None and e[6] not in seen and e[3] != "crash":
            seen.add(e[6]); sids.append(e[6])
    # jitter window estimate
    ts = [e[1] for e in evs]
    gaps = [ts[k + 1] - ts[k] for k in range(len(ts) - 1) if ts[k + 1] > ts[k]]
    base = statistics.median(gaps) if gaps else 1
    obs = 0
    lastw = {}
    for e in evs:
        if e[6] is None or e[3] not in ("write", "checkpoint", "commit"):
            continue
        p = lastw.get(e[6])
        if p is not None and e[4] is not None and p[1] is not None and e[4] < p[1]:
            obs = max(obs, e[1] - p[0])
        if e[4] is not None:
            end = e[4] + (e[5] or 0)
            if p is None or p[1] is None or end > p[1]:
                lastw[e[6]] = (e[1], end)
    W = float(max(3.0 * base, 1.5 * obs, 3.0))
    # duplicate candidates: earlier events with identical node/type/off/len
    sigmap = {}
    dupc = [[] for _ in evs]
    origset = set()
    for k, e in enumerate(evs):
        if e[3] in ("open", "crash"):
            continue
        sig = (e[2], e[3], e[4], e[5])
        lst = sigmap.get(sig)
        if lst:
            dupc[k] = lst[-3:]
            for j in dupc[k]:
                origset.add(j)
            lst.append(k)
        else:
            sigmap[sig] = [k]
    state["_prep"] = {"evs": evs, "sids": sids, "W": W, "dupc": dupc, "orig": sorted(origset)}
    return state


def beam_search(state, params):
    t0 = time.process_time()
    budget = 0.65
    P = state["_prep"]
    evs = P["evs"]; sids = P["sids"]; W = float(P["W"]); dupc = P["dupc"]
    origset = set(P["orig"])
    S = len(sids)
    sidx = {s: k for k, s in enumerate(sids)}
    nE = max(1, len(evs))
    K = 48

    def add_gap(gaps, a, b):
        g = gaps + ((a, b),)
        if len(g) > 6:
            g = g[-6:]
        return g

    def apply_active(ss, typ, node, off, ln, t, c0):
        st, nd, cur, dur, tm, gaps, fr = ss
        out = []
        if typ == "write":
            if off is None:
                out.append((c0 + 1.0, (ACT, node, cur + (ln or 0), dur, tm, gaps, -1)))
                return out
            L = ln or 0
            if off == cur:
                out.append((c0, (ACT, node, cur + L, dur, tm, gaps, -1)))
            elif off > cur:
                out.append((c0 + GAP, (ACT, node, off + L, dur, tm, add_gap(gaps, cur, off), -1)))
            else:
                done = False
                for gi, (a, b) in enumerate(gaps):
                    if a <= off and off + L <= b:
                        ng = list(gaps[:gi])
                        refund = GAP
                        if a < off:
                            ng.append((a, off)); refund = 0.0
                        if off + L < b:
                            ng.append((off + L, b)); refund = 0.0
                        ng.extend(gaps[gi + 1:])
                        out.append((c0 + JIT - refund, (ACT, node, cur, dur, tm, tuple(ng), -1)))
                        done = True
                        break
                if not done:
                    out.append((c0 + IMPOSS, (ACT, node, max(cur, off + L), dur, tm, gaps, -1)))
            return out
        if typ == "checkpoint" or typ == "commit":
            o = cur if off is None else off
            ns = COMM if typ == "commit" else ACT
            ntm = t if typ == "commit" else tm
            if o == cur:
                out.append((c0, (ns, node, o, o, ntm, gaps if ns == ACT else (), -1)))
            elif o > cur:
                out.append((c0 + GAP, (ns, node, o, o, ntm, add_gap(gaps, cur, o) if ns == ACT else (), -1)))
            else:
                if typ == "commit":
                    out.append((c0 + IMPOSS * 0.5, (COMM, node, o, o, t, (), -1)))
                else:
                    pen = JIT if o >= dur else IMPOSS * 0.5
                    out.append((c0 + pen, (ACT, node, cur, max(dur, o), tm, gaps, -1)))
            return out
        if typ == "abort":
            out.append((c0 + ABORT_C, (ABOR, node, dur, dur, t, (), -1)))
            return out
        return out

    def opts(ss, typ, node, off, ln, t):
        st = ss[0]
        if st == ACT:
            if typ == "recover":
                o = ss[3] if off is None else off
                return [(IMPOSS, (ACT, node, o, o, ss[4], (), t))]
            if node != ss[1]:
                return apply_active(ss, typ, node, off, ln, t, CROSS)
            return apply_active(ss, typ, node, off, ln, t, 0.0)
        if st == DOWN:
            dur = ss[3]
            out = []
            if typ == "recover":
                o = dur if off is None else off
                if o == dur:
                    c = 0.0
                elif o > dur:
                    c = GAP
                else:
                    c = IMPOSS
                out.append((c, (ACT, node, o, o, ss[4], (), t)))
                return out
            dt = t - ss[4]
            if node == ss[1] and dt <= 3 * W:
                c = LATE + dt / W
                if typ == "write":
                    if off is None or off >= dur:
                        out.append((c, ss))
                    else:
                        out.append((c + 4.0, ss))
                elif typ == "checkpoint":
                    o = dur if off is None else off
                    nd = max(dur, o)
                    out.append((c, (DOWN, ss[1], nd, nd, ss[4], (), -1)))
                elif typ == "commit":
                    o = dur if off is None else off
                    out.append((c, (COMM, ss[1], o, o, t, (), -1)))
                elif typ == "abort":
                    out.append((c, (ABOR, ss[1], dur, dur, t, (), -1)))
            v = (ACT, node, dur, dur, ss[4], (), -1)
            out.extend(apply_active(v, typ, node, off, ln, t, REC_MISS))
            return out
        if st == COMM or st == ABOR:
            dt = t - ss[4]
            if node == ss[1] and dt <= 3 * W and typ != "recover":
                c = LATE + dt / W
                if typ == "checkpoint" and st == ABOR and off is not None and off > ss[3]:
                    return [(c, (ABOR, ss[1], off, off, ss[4], (), -1))]
                if typ in ("write", "checkpoint") and st == COMM and off is not None and off > ss[3]:
                    c += 4.0
                if typ in ("commit", "abort"):
                    c += 3.0
                return [(c, ss)]
            return []
        return []

    init = tuple((NEW, None, 0, 0, 0, (), -1) for _ in range(S))
    beam = [(0.0, init, (), None)]
    for ei, e in enumerate(evs):
        i, t, node, typ, off, ln, sid, _k = e
        el = time.process_time() - t0
        if ei > 0 and ei % 10 == 0:
            rem = budget - el
            per = el / ei
            left = nE - ei
            if per * left > rem:
                K = max(2, int(K * 0.7))
            elif per * left < 0.4 * rem and K < 96:
                K = min(96, K + 4)
        if el > budget * 1.15:
            K = 1
            if len(beam) > 1:
                beam = [min(beam, key=lambda h: h[0])]
        if typ == "crash":
            nb = []
            for (c, ss, og, lk) in beam:
                lst = list(ss)
                spare = []
                for k in range(S):
                    s = lst[k]
                    if s[0] == ACT and s[1] == node:
                        if s[6] >= 0 and t - s[6] <= W:
                            spare.append(k)
                        lst[k] = (DOWN, node, s[3], s[3], t, (), -1)
                nb.append((c, tuple(lst), og, lk))
                for k in spare[:3]:
                    l2 = list(lst); l2[k] = ss[k]
                    nb.append((c + SPARE, tuple(l2), og, lk))
            nb.sort(key=lambda h: h[0])
            beam = nb[:max(K, 1)]
            continue
        if typ == "open":
            if sid not in sidx:
                continue
            k = sidx[sid]
            nb = []
            for (c, ss, og, lk) in beam:
                s = ss[k]
                if s[0] == NEW:
                    ns = (ACT, node, 0, 0, 0, (), t)
                    cc = c
                else:
                    ns = s; cc = c + IMPOSS
                nb.append((cc, ss[:k] + (ns,) + ss[k + 1:], og, lk))
            beam = nb
            continue
        anon = sid is None or sid not in sidx
        isorig = ei in origset
        cands = []
        dc = dupc[ei]
        known = None if anon else sidx[sid]
        for hid, (c, ss, og, lk) in enumerate(beam):
            got = False
            if dc and og:
                dd = dict(og)
                for j in dc:
                    s2 = dd.get(j)
                    if s2 is not None and (known is None or s2 == known):
                        cands.append((c + DUP, hid, s2, None))
                        got = True
                        break
            if known is not None:
                o = opts(ss[known], typ, node, off, ln, t)
                for (cc, ns) in o:
                    cands.append((c + cc, hid, known, ns))
                    got = True
                if not got:
                    cands.append((c + 20.0, hid, known, None))
                continue
            for k in range(S):
                s = ss[k]
                st = s[0]
                if st == NEW:
                    continue
                if st == ACT and (typ == "recover" or s[1] != node):
                    continue
                for (cc, ns) in opts(s, typ, node, off, ln, t):
                    cands.append((c + cc, hid, k, ns))
                    got = True
            if not got:
                best = None
                for k in range(S):
                    s = ss[k]
                    if s[0] == NEW:
                        continue
                    if s[0] == ACT:
                        for (cc, ns) in opts(s, typ, node, off, ln, t):
                            if best is None or c + cc < best[0]:
                                best = (c + cc, hid, k, ns)
                    if best is None and s[1] == node:
                        best = (c + 20.0, hid, k, None)
                if best is None:
                    for k in range(S):
                        if ss[k][0] != NEW:
                            best = (c + 30.0, hid, k, None)
                            break
                if best is None and S > 0:
                    best = (c + 40.0, hid, 0, None)
                if best is not None:
                    cands.append(best)
        if not cands:
            continue
        if len(cands) > 4 * K:
            cands = heapq.nsmallest(4 * K, cands, key=lambda x: (x[0], x[1], x[2]))
        else:
            cands.sort(key=lambda x: (x[0], x[1], x[2]))
        nb = []
        keys = set()
        for (cc, hid, k, ns) in cands:
            c, ss, og, lk = beam[hid]
            nss = ss if ns is None else ss[:k] + (ns,) + ss[k + 1:]
            if nss in keys:
                continue
            keys.add(nss)
            nog = og + ((ei, k),) if isorig else og
            nlk = (i, k, lk) if anon else lk
            nb.append((cc, nss, nog, nlk))
            if len(nb) >= K:
                break
        beam = nb
    if beam:
        best = min(beam, key=lambda h: h[0])
    else:
        best = (0.0, init, (), None)
    assign = {}
    lk = best[3]
    while lk is not None:
        assign[str(lk[0])] = sids[lk[1]]
        lk = lk[2]
    for e in evs:
        if e[3] != "crash" and (e[6] is None or e[6] not in sidx):
            if str(e[0]) not in assign:
                cand = None
                for e2 in evs:
                    if e2[2] == e[2] and e2[6] in sidx:
                        cand = e2[6]
                if cand is None and sids:
                    cand = sids[0]
                if cand is not None:
                    assign[str(e[0])] = cand
    sessions = {}
    for k, s in enumerate(sids):
        ss = best[1][k]
        sessions[s] = {"status": STNAME[ss[0]], "durable": int(ss[3])}
    state["output"] = {"assignments": assign, "sessions": sessions}
    state.pop("_prep", None)
    return state

import time

GAP = 2.0
LATE = 3.0
MISSREC = 2.5
DUPC = 0.5
BIG = 20.0
TYPES = {"open": 0, "write": 1, "checkpoint": 2, "commit": 3, "abort": 4, "recover": 5, "crash": 6}


def prepare(state, params):
    inp = state.get("input") or {}
    raw = [e for e in (inp.get("events") or []) if isinstance(e, dict)]
    evs = []
    for k, e in enumerate(raw):
        try:
            t = int(e.get("t") or 0)
        except Exception:
            t = 0
        idx = e.get("i", k)
        evs.append({"i": idx, "t": t, "node": str(e.get("node")), "type": str(e.get("type")),
                    "off": e.get("off"), "len": e.get("len"), "sid": e.get("sid"), "k": k})
    evs.sort(key=lambda e: (e["t"], e["k"]))
    state["prep"] = evs
    return state


def estimate_window(evs):
    ts = [e["t"] for e in evs]
    gaps = sorted(b - a for a, b in zip(ts, ts[1:]) if b > a)
    g = gaps[len(gaps) // 2] if gaps else 1
    maxinv = 0
    last = {}
    for e in evs:
        if e["type"] != "write" or e["sid"] is None or e["off"] is None or e["len"] is None:
            continue
        p = last.get(e["sid"])
        if p is not None and e["off"] + e["len"] == p["off"]:
            maxinv = max(maxinv, e["t"] - p["t"])
        last[e["sid"]] = e
    return max(6 * g, 2.5 * maxinv, 3)


def solve(state, params):
    t0 = time.perf_counter()
    BUDGET = 0.72
    evs = state.get("prep") or []
    nodes_l = []
    for e in evs:
        if e["node"] not in nodes_l:
            nodes_l.append(e["node"])
    nid = {n: k for k, n in enumerate(nodes_l)}
    sids = []
    for e in evs:
        if e["type"] == "open" and e["sid"] is not None and e["sid"] not in sids:
            sids.append(e["sid"])
    for e in evs:
        if e["sid"] is not None and e["type"] != "crash" and e["sid"] not in sids:
            sids.append(e["sid"])
    S = len(sids)
    sidx = {s: k for k, s in enumerate(sids)}
    W = estimate_window(evs)
    DW = 3 * W + 5

    E = []
    for e in evs:
        off = e["off"] if isinstance(e["off"], int) else None
        ln = e["len"] if isinstance(e["len"], int) else None
        E.append((TYPES.get(e["type"], 1), nid[e["node"]], off, ln, e["t"],
                  sidx.get(e["sid"]) if e["sid"] is not None else None))
    n = len(E)
    origs = [[] for _ in range(n)]
    lastdup = {}
    bysig = {}
    for j in range(n):
        ty, nd, off, ln, t, sj = E[j]
        if ty == 6:
            continue
        sig = (ty, nd, off, ln)
        lst = bysig.setdefault(sig, [])
        for i in lst:
            if t - E[i][4] <= DW:
                origs[j].append(i)
                lastdup[i] = j
        lst.append(j)

    # session tuple: (status, node, off, dur, crash/end node, crash/end time, pre-crash off, pend node, pend t)
    def trans(s, ty, node, off, ln, t):
        st, sn, so, sd, xn, xt, pre, pn, pt = s
        if st == 1:
            if ty == 5:
                if off is None:
                    return LATE + 1.0, (1, node, sd, sd, xn, xt, pre, sn, t)
                if sd <= off <= so:
                    return LATE + 1.0, (1, node, off, off, xn, xt, pre, sn, t)
                return BIG, (1, node, off, max(sd, off), xn, xt, pre, sn, t)
            if sn != node:
                return None
            if ty == 1:
                if off is None:
                    return 1.0, s
                end = off + (ln or 0)
                if off == so:
                    return 0.0, (1, sn, end, sd, xn, xt, pre, pn, pt)
                if off > so:
                    return GAP, (1, sn, end, sd, xn, xt, pre, pn, pt)
                if end <= so:
                    return LATE, s
                return BIG * 0.5, (1, sn, end, sd, xn, xt, pre, pn, pt)
            if ty == 2:
                if off is None or off == so:
                    return 0.0, (1, sn, so, so, xn, xt, pre, pn, pt)
                if off > so:
                    return GAP, (1, sn, off, off, xn, xt, pre, pn, pt)
                return LATE, (1, sn, so, max(sd, off), xn, xt, pre, pn, pt)
            if ty == 3:
                if off is None:
                    off = so
                c = 0.0 if off == so else (GAP if off > so else LATE + 1.0)
                return c, (3, sn, off, off, xn, t, pre, -1, 0)
            if ty == 4:
                return 0.0, (4, sn, so, sd, xn, t, pre, -1, 0)
            return 0.0, s
        if st == 2:
            best = None
            recent = (node == xn and t - xt <= W)
            if ty == 5:
                if off is None or off == sd:
                    return 0.0, (1, node, sd, sd, xn, xt, pre, -1, 0)
                if off > sd:
                    return GAP, (1, node, off, off, xn, xt, pre, -1, 0)
                return GAP * 2, (1, node, off, sd, xn, xt, pre, -1, 0)
            if ty == 1:
                if off is None:
                    return LATE, s
                end = off + (ln or 0)
                if recent and off <= pre:
                    if off == pre:
                        best = (LATE - 1.0, (2, sn, so, sd, xn, xt, end, pn, pt))
                    elif end <= pre:
                        best = (LATE, s)
                if off >= sd:
                    c = MISSREC + (GAP if off > sd else 0.0)
                    if best is None or c < best[0]:
                        best = (c, (1, node, end, sd, xn, xt, pre, -1, 0))
                return best
            if ty == 2 or ty == 3:
                if off is None:
                    off = sd
                if recent and sd <= off <= pre:
                    if ty == 2:
                        best = (LATE, (2, sn, off, off, xn, xt, pre, pn, pt))
                    else:
                        best = (LATE, (3, sn, off, off, xn, t, pre, -1, 0))
                if off >= sd:
                    c = MISSREC + (GAP if off > sd else 0.0)
                    if best is None or c < best[0]:
                        if ty == 2:
                            best = (c, (1, node, off, off, xn, xt, pre, -1, 0))
                        else:
                            best = (c, (3, node, off, off, xn, t, pre, -1, 0))
                return best
            if ty == 4:
                if recent:
                    return LATE, (4, sn, so, sd, xn, t, pre, -1, 0)
                return MISSREC, (4, node, so, sd, xn, t, pre, -1, 0)
            return None
        if st == 3 or st == 4:
            if t - xt <= W and (sn == node or ty == 5):
                if ty == 1 and off is not None and st == 3 and off + (ln or 0) > so:
                    return BIG * 0.5, s
                return LATE + 0.5, s
            return BIG, s
        return None

    def apply_crash(states, node, t):
        out = None
        for k in range(S):
            s = states[k]
            if s[0] == 1 and s[1] == node:
                if s[7] == node and t - s[8] <= W:
                    ns = (1, s[1], s[2], s[3], s[4], s[5], s[6], -1, 0)
                else:
                    ns = (2, s[1], s[3], s[3], node, t, s[2], -1, 0)
                if out is None:
                    out = list(states)
                out[k] = ns
        return tuple(out) if out is not None else states

    init = tuple((0, -1, 0, 0, -1, 0, 0, -1, 0) for _ in range(S))
    beam = [(0.0, init, (), None)]
    K = int(state.get("beamK", 48)) if S > 0 else 1
    MARGIN = 9.0
    for j in range(n):
        ty, node, off, ln, t, known = E[j]
        if ty == 6:
            beam = [(c, apply_crash(st, node, t), dm, lk) for (c, st, dm, lk) in beam]
            continue
        el = time.perf_counter() - t0
        if j > 10 and el > BUDGET * (j / n) * 1.1 and K > 2:
            K = max(2, K // 2)
        if el > BUDGET * 1.3:
            K = 1
        is_orig = j in lastdup
        cands = []
        oj = origs[j]
        for hi in range(len(beam)):
            c0, states, dm, lk = beam[hi]
            opts = {}
            if oj and dm:
                dmd = dict(dm)
                for i in oj:
                    sk = dmd.get(i)
                    if sk is not None and (known is None or known == sk):
                        if sk not in opts or opts[sk][0] > DUPC:
                            opts[sk] = (DUPC, None)
            if ty == 0:
                sk = known
                if sk is None and not opts:
                    for k in range(S):
                        if states[k][0] == 0:
                            sk = k
                            break
                    if sk is None and S:
                        sk = 0
                if sk is not None and S:
                    s = states[sk]
                    if s[0] == 0:
                        opts[sk] = (0.0, (1, node, 0, 0, -1, 0, 0, -1, 0))
                    elif sk not in opts:
                        opts[sk] = (DUPC, None)
            elif known is not None:
                r = trans(states[known], ty, node, off, ln, t)
                if r is None:
                    r = (BIG, states[known])
                if known not in opts or r[0] < opts[known][0]:
                    opts[known] = r
            else:
                for k in range(S):
                    s = states[k]
                    st = s[0]
                    if st == 0:
                        continue
                    if st != 2 and s[1] != node and ty != 5:
                        continue
                    r = trans(s, ty, node, off, ln, t)
                    if r is None:
                        continue
                    if k not in opts or r[0] < opts[k][0]:
                        opts[k] = r
                if not opts:
                    for k in range(S):
                        if states[k][0] != 0:
                            opts[k] = (BIG * 2, None)
                            break
                    if not opts and S:
                        opts[0] = (BIG * 2, None)
            if not opts:
                cands.append((c0, hi, -1, None))
                continue
            mn = min(v[0] for v in opts.values())
            for k, (c, ns) in opts.items():
                if c <= mn + MARGIN:
                    cands.append((c0 + c, hi, k, ns))
        cands.sort(key=lambda x: x[0])
        nb = []
        seen = set()
        for (c, hi, k, ns) in cands:
            _, states, dm, lk = beam[hi]
            if k >= 0 and ns is not None and ns != states[k]:
                st2 = states[:k] + (ns,) + states[k + 1:]
            else:
                st2 = states
            if dm:
                dm2 = tuple(p for p in dm if lastdup.get(p[0], -1) > j)
            else:
                dm2 = dm
            if is_orig and k >= 0:
                dm2 = dm2 + ((j, k),)
            key = (st2, dm2)
            if key in seen:
                continue
            seen.add(key)
            nb.append((c, st2, dm2, (j, k, lk)))
            if len(nb) >= K:
                break
        if nb:
            beam = nb
    best = min(beam, key=lambda h: h[0]) if beam else (0.0, init, (), None)
    assign = {}
    lk = best[3]
    while lk is not None:
        j, k, lk = lk
        assign[j] = k
    out_a = {}
    for j, e in enumerate(evs):
        if e["type"] != "crash" and e["sid"] is None:
            k = assign.get(j, -1)
            out_a[str(e["i"])] = sids[k] if 0 <= k < S else (sids[0] if sids else "")
    sess = {}
    names = {0: "active", 1: "active", 2: "down", 3: "committed", 4: "aborted"}
    for k, s in enumerate(sids):
        st = best[1][k]
        sess[s] = {"status": names[st[0]], "durable": int(st[3])}
    state["output"] = {"assignments": out_a, "sessions": sess}
    return state

import heapq
import time
from collections import defaultdict

SES_TYPES = ("open", "write", "checkpoint", "commit", "abort", "recover")


def _int(v):
    if v is None or isinstance(v, bool):
        return None
    try:
        return int(v)
    except Exception:
        try:
            return int(float(v))
        except Exception:
            return None


def _parse(state):
    inp = state.get("input") or {}
    raw = inp.get("events") or []
    ev = []
    for k, e in enumerate(raw):
        if not isinstance(e, dict):
            continue
        typ = str(e.get("type") or "").strip().lower()
        i = e.get("i")
        if i is None:
            i = k
        t = _int(e.get("t"))
        if t is None:
            t = k
        off = _int(e.get("off"))
        ln = _int(e.get("len"))
        sid = e.get("sid")
        if sid is not None:
            sid = str(sid)
        node = str(e.get("node"))
        pre = None
        post = None
        if typ == "open":
            post = 0
        elif typ == "write":
            pre = off
            if off is not None:
                post = off + (ln if ln is not None else 0)
        elif typ == "checkpoint":
            pre = off
            post = off
        elif typ == "commit":
            pre = off
        elif typ == "recover":
            post = off
        ev.append({"k": len(ev), "i": i, "t": t, "node": node, "type": typ,
                   "off": off, "len": ln, "sid": sid, "sid0": sid,
                   "pre": pre, "post": post, "pos": len(ev)})
    return ev


def _median(xs, default):
    if not xs:
        return default
    s = sorted(xs)
    return s[len(s) // 2]


def _fp(e):
    return (e["node"], e["type"], e["off"], e["len"])


def _core(ev, t_start):
    crashes = defaultdict(list)
    for e in ev:
        if e["type"] == "crash":
            crashes[e["node"]].append(e["t"])
    for v in crashes.values():
        v.sort()
    sess_ev = [e for e in ev if e["type"] in SES_TYPES]
    opens = {}
    for e in sess_ev:
        if e["type"] == "open" and e["sid"] is not None and e["sid"] not in opens:
            opens[e["sid"]] = e["k"]

    ts = sorted(e["t"] for e in ev)
    gaps = [ts[j + 1] - ts[j] for j in range(len(ts) - 1) if ts[j + 1] > ts[j]]
    g0 = max(1.0, float(_median(gaps, 1)))

    # ---------------- duplicate merging by fingerprint ----------------
    DUPW = 25.0 * g0
    alias = {}
    byfp = defaultdict(list)
    for e in sess_ev:
        if e["type"] == "open":
            continue
        byfp[_fp(e)].append(e)
    for key, lst in byfp.items():
        if len(lst) < 2:
            continue
        typ = key[1]
        off = key[2]
        if typ == "abort" or off is None or off == 0:
            continue
        lst.sort(key=lambda e: (e["t"], e["pos"]))
        used = set()
        for a in range(len(lst)):
            x = lst[a]
            if x["k"] in alias or x["k"] in used:
                continue
            for b in range(a + 1, len(lst)):
                y = lst[b]
                if y["k"] in alias or y["k"] in used:
                    continue
                if y["t"] - x["t"] > DUPW:
                    break
                if x["sid"] is not None and y["sid"] is not None and x["sid"] != y["sid"]:
                    continue
                alias[y["k"]] = x["k"]
                used.add(x["k"])
                if x["sid"] is None and y["sid"] is not None:
                    x["sid"] = y["sid"]
                break
    act = [e for e in sess_ev if e["k"] not in alias]
    E = {e["k"]: e for e in act}

    def crash_between(node, t1, t2):
        lst = crashes.get(node)
        if not lst:
            return None
        for c in lst:
            if t1 <= c <= t2:
                return c
        return None

    by_pre = defaultdict(list)
    for e in act:
        if e["pre"] is not None and e["type"] in ("write", "checkpoint", "commit"):
            by_pre[(e["node"], e["pre"])].append(e)

    # ---------------- phase 1: exact offset links, sparse greedy min-cost matching ----------------
    def phase1(W, S, J):
        links = []
        for x in act:
            if x["post"] is None or x["type"] in ("commit", "abort"):
                continue
            for y in by_pre.get((x["node"], x["post"]), ()):
                if y["k"] == x["k"]:
                    continue
                if x["sid"] is not None and y["sid"] is not None and x["sid"] != y["sid"]:
                    continue
                dt = y["t"] - x["t"]
                if dt < -W:
                    continue
                if dt == 0 and y["pos"] < x["pos"] and x["type"] != "open":
                    dt = -0.5
                c = dt if dt >= 0 else 1.8 * (-dt) + 0.3 * S
                if crash_between(x["node"], x["t"] + J, y["t"]) is not None:
                    c += 6.0 * S
                elif crash_between(x["node"], x["t"] - J, y["t"] + J) is not None:
                    c += 1.0 * S
                links.append((c, x["pos"], y["pos"], x["k"], y["k"], dt))
        links.sort()
        par = {e["k"]: e["k"] for e in act}
        lab = {e["k"]: e["sid"] for e in act}

        def find(a):
            while par[a] != a:
                par[a] = par[par[a]]
                a = par[a]
            return a
        succ = {}
        pred = {}
        acc_dt = []
        for c, _, _, xk, yk, dt in links:
            if xk in succ or yk in pred:
                continue
            rx, ry = find(xk), find(yk)
            if rx == ry:
                continue
            lx, ly = lab[rx], lab[ry]
            if lx is not None and ly is not None and lx != ly:
                continue
            succ[xk] = yk
            pred[yk] = xk
            par[ry] = rx
            lab[rx] = lx if lx is not None else ly
            acc_dt.append(dt)
        return succ, pred, acc_dt

    succ, pred, acc_dt = phase1(40.0 * g0, 3.0 * g0, 2.0 * g0)
    pos_dt = [d for d in acc_dt if d > 0]
    S = max(1.0, float(_median(pos_dt, 3.0 * g0)))
    negs = sorted(-d for d in acc_dt if d < 0)
    if len(negs) >= 3:
        J = float(negs[-2])
    elif negs:
        J = float(negs[-1])
    else:
        J = 0.0
    J = min(max(J, 0.0), 30.0 * g0)
    succ, pred, acc_dt = phase1(J * 1.3 + g0 + 1.0, S, J)

    # ---------------- fragments ----------------
    frag_of = {}
    frags = []
    for e in sorted(act, key=lambda e: (e["t"], e["pos"])):
        if e["k"] in pred:
            continue
        chain = []
        cur = e["k"]
        seen = set()
        while cur is not None and cur not in seen:
            seen.add(cur)
            chain.append(cur)
            cur = succ.get(cur)
        fid = len(frags)
        frags.append(chain)
        for k in chain:
            frag_of[k] = fid
    for e in act:
        if e["k"] not in frag_of:
            fid = len(frags)
            frags.append([e["k"]])
            frag_of[e["k"]] = fid

    comp_frags = {f: [f] for f in range(len(frags))}
    version = defaultdict(int)

    def comp_events(c):
        out = []
        for f in comp_frags[c]:
            out.extend(frags[f])
        return out

    def summary(c):
        es = [E[k] for k in comp_events(c)]
        rooted = es[0]["type"] == "open"
        sid = None
        for e in es:
            if e["sid"] is not None:
                sid = e["sid"]
                break
        dur = 0 if rooted else None
        lastpost = None
        for e in es:
            ty = e["type"]
            if ty in ("checkpoint", "recover", "commit") and e["off"] is not None:
                dur = e["off"] if dur is None else max(dur, e["off"])
            if ty == "write" and lastpost is not None and e["pre"] is not None and e["pre"] < lastpost:
                dur = e["pre"] if dur is None else max(dur, e["pre"])
            if e["post"] is not None:
                lastpost = e["post"]
        return {"head": es[0], "tail": es[-1], "sid": sid, "dur": dur}

    def link_cost(sa, sb):
        a = sa["tail"]
        b = sb["head"]
        if a["type"] in ("commit", "abort") or b["type"] == "open":
            return None
        if sa["sid"] is not None and sb["sid"] is not None and sa["sid"] != sb["sid"]:
            return None
        dt = b["t"] - a["t"]
        if dt < -(J + g0):
            return None
        tc = dt if dt >= 0 else 2.0 * (-dt)
        bt = b["type"]
        if _fp(a) == _fp(b) and abs(dt) <= DUPW and bt != "abort":
            return 0.2 * S + 0.1 * abs(dt)
        crash = crash_between(a["node"], a["t"] - J, b["t"] + J)
        crash_strict = crash_between(a["node"], a["t"], b["t"])
        dur = sa["dur"]
        if bt == "recover":
            if crash is None or b["off"] is None:
                return None
            if a["post"] is not None and b["off"] > a["post"]:
                return None
            c = tc + 0.5 * S
            if dur is None:
                c += 3.0 * S
            elif b["off"] == dur:
                pass
            elif b["off"] > dur:
                c += 4.0 * S
            else:
                return None
            if crash_strict is None:
                c += 1.0 * S
            return c
        if bt == "abort":
            if b["node"] != a["node"]:
                return None
            c = tc + 2.0 * S
            if crash_strict is not None:
                c += 6.0 * S
            return c
        if b["pre"] is None or a["post"] is None:
            return None
        best = None
        if b["node"] == a["node"] and crash_strict is None:
            if b["pre"] == a["post"]:
                best = tc + 0.5 * S
            elif b["pre"] > a["post"]:
                best = tc + 4.0 * S
        if crash is not None:
            c = None
            if dur is not None and b["pre"] == dur and b["pre"] <= a["post"]:
                c = tc + 5.0 * S
            elif (dur is None or b["pre"] >= dur) and b["pre"] <= a["post"]:
                c = tc + 9.0 * S
            if c is not None and (best is None or c < best):
                best = c
        return best

    cpar = list(range(len(frags)))

    def cfind(a):
        while cpar[a] != a:
            cpar[a] = cpar[cpar[a]]
            a = cpar[a]
        return a

    summ = {c: summary(c) for c in comp_frags}
    heads = [c for c in comp_frags if summ[c]["head"]["type"] != "open"]
    heads.sort(key=lambda c: summ[c]["head"]["t"])
    head_t = [summ[c]["head"]["t"] for c in heads]
    tails = [c for c in comp_frags if summ[c]["tail"]["type"] not in ("commit", "abort")]
    heap = []
    KMAX = 90
    import bisect as _bs
    for ca in tails:
        if time.perf_counter() - t_start > 0.45:
            break
        sa = summ[ca]
        lo_t = sa["tail"]["t"] - J - g0
        j0 = _bs.bisect_left(head_t, lo_t)
        cnt = 0
        for jj in range(j0, len(heads)):
            cb = heads[jj]
            if cb == ca:
                continue
            c = link_cost(sa, summ[cb])
            if c is not None:
                heap.append((c, sa["tail"]["pos"], summ[cb]["head"]["pos"], ca, cb, 0, 0))
                cnt += 1
                if cnt >= KMAX:
                    break
    heapq.heapify(heap)
    head_free = set(heads)
    tail_free = set(tails)
    while heap:
        if time.perf_counter() - t_start > 0.6:
            break
        c, p1, p2, ca, cb, va, vb = heapq.heappop(heap)
        if ca not in tail_free or cb not in head_free:
            continue
        ra = cfind(ca)
        rb = cfind(cb)
        if ra == rb:
            continue
        if va != version[ra] or vb != version[rb]:
            nc = link_cost(summary(ra), summary(rb))
            if nc is None:
                continue
            heapq.heappush(heap, (nc, p1, p2, ca, cb, version[ra], version[rb]))
            continue
        tail_free.discard(ca)
        head_free.discard(cb)
        comp_frags[ra] = comp_frags[ra] + comp_frags[rb]
        del comp_frags[rb]
        cpar[rb] = ra
        version[ra] += 1
        version[rb] += 1

    # ---------------- sessions ----------------
    comps = {r: comp_events(r) for r in list(comp_frags.keys())}
    comp_sid = {}
    for r, ks in comps.items():
        sid = None
        for k in ks:
            if E[k]["type"] == "open" and E[k]["sid"] is not None:
                sid = E[k]["sid"]
                break
        if sid is None:
            for k in ks:
                if E[k]["sid"] is not None:
                    sid = E[k]["sid"]
                    break
        if sid is not None:
            comp_sid[r] = sid
    sess_keys = defaultdict(list)
    for r, sid in comp_sid.items():
        sess_keys[sid].extend(comps[r])
    all_sids = list(opens.keys())
    for sid in list(sess_keys.keys()):
        if sid not in all_sids:
            all_sids.append(sid)

    orphans = [r for r in comps if r not in comp_sid]
    orphans.sort(key=lambda r: E[comps[r][0]]["t"])
    for r in orphans:
        ks = comps[r]
        h = E[ks[0]]
        best = None
        bsid = None
        ofps = set(_fp(E[k]) for k in ks)
        for sid in all_sids:
            sc = None
            for k in sess_keys.get(sid, []):
                e = E[k]
                if e["type"] != "open" and _fp(e) in ofps and abs(e["t"] - h["t"]) <= DUPW:
                    v = -100.0 * S + abs(e["t"] - h["t"])
                    if sc is None or v < sc:
                        sc = v
                    continue
                if e["node"] != h["node"]:
                    continue
                d = h["t"] - e["t"]
                v = d if d >= 0 else 2.0 * (-d) + S
                if h["pre"] is not None and e["post"] is not None:
                    if h["pre"] == e["post"]:
                        v -= 2.0 * S
                    elif h["pre"] < e["post"]:
                        v += 3.0 * S
                if e["type"] in ("commit", "abort") and d > 0:
                    v += 5.0 * S
                if sc is None or v < sc:
                    sc = v
            if sc is None:
                continue
            if best is None or sc < best:
                best = sc
                bsid = sid
        if bsid is None:
            bd = None
            for sid in all_sids:
                for k in sess_keys.get(sid, []):
                    d = abs(E[k]["t"] - h["t"])
                    if bd is None or d < bd:
                        bd = d
                        bsid = sid
        if bsid is None and all_sids:
            bsid = all_sids[0]
        if bsid is not None:
            sess_keys[bsid].extend(ks)

    owner = {}
    for sid, ks in sess_keys.items():
        for k in ks:
            owner[k] = sid
    for k, base in alias.items():
        if base in owner:
            owner[k] = owner[base]

    # ---------------- final states ----------------
    sessions = {}
    for sid in all_sids:
        ks = list(sess_keys.get(sid, []))
        if sid in opens and opens[sid] not in ks:
            ks.insert(0, opens[sid])
        es = []
        for k in ks:
            e = E[k]
            tw = False
            for p in es:
                if p["type"] != "open" and _fp(p) == _fp(e) and abs(p["t"] - e["t"]) <= DUPW:
                    tw = True
                    break
            if not tw:
                es.append(e)
        status = None
        dur = 0
        lastpost = None
        commit_off = None
        for e in es:
            ty = e["type"]
            if ty == "commit":
                status = "committed"
                if e["off"] is not None:
                    commit_off = e["off"] if commit_off is None else max(commit_off, e["off"])
            elif ty == "abort" and status is None:
                status = "aborted"
            if ty in ("checkpoint", "recover") and e["off"] is not None:
                dur = max(dur, e["off"])
            if ty == "write" and lastpost is not None and e["pre"] is not None and e["pre"] < lastpost:
                dur = max(dur, e["pre"])
            if e["post"] is not None:
                lastpost = e["post"]
        if status == "committed" and commit_off is not None:
            dur = commit_off
        if status is None:
            status = "active"
            if es:
                last = max(es, key=lambda e: (e["t"], e["pos"]))
                node = last["node"]
                lo = last["t"] - J
                if last["type"] == "recover":
                    lo = last["t"]
                for e in es:
                    if e["type"] == "recover" and e["node"] == node:
                        lo = max(lo, e["t"])
                for c in crashes.get(node, []):
                    if c > lo or (c == lo and last["type"] != "recover"):
                        status = "down"
                        break
        sessions[sid] = {"status": status, "durable": int(dur)}
    return owner, sessions, all_sids


def _fallback(ev):
    sids = []
    for e in ev:
        if e["type"] == "open" and e["sid"] is not None and e["sid"] not in sids:
            sids.append(e["sid"])
    return {}, {s: {"status": "active", "durable": 0} for s in sids}, sids


def solve(state, params):
    t_start = time.perf_counter()
    ev = _parse(state)
    try:
        owner, sessions, all_sids = _core(ev, t_start)
    except Exception:
        owner, sessions, all_sids = _fallback(ev)
    known = [e for e in ev if e["type"] != "crash" and owner.get(e["k"]) is not None]
    assignments = {}
    for e in ev:
        if e["type"] == "crash" or e["sid0"] is not None:
            continue
        sid = owner.get(e["k"])
        if sid is None:
            best = None
            for f in known:
                d = abs(f["t"] - e["t"]) + (0 if f["node"] == e["node"] else 1000000)
                if best is None or d < best:
                    best = d
                    sid = owner[f["k"]]
        if sid is None:
            sid = all_sids[0] if all_sids else ""
        assignments[str(e["i"])] = sid
    for sid in all_sids:
        if sid not in sessions:
            sessions[sid] = {"status": "active", "durable": 0}
    state["output"] = {"assignments": assignments, "sessions": sessions}
    return state

import bisect
import math
import time
from collections import defaultdict


def prep_events(state, params):
    inp = state.get("input") or {}
    raw = inp.get("events") or []
    ev = []
    for k, e in enumerate(raw):
        if not isinstance(e, dict):
            continue
        typ = str(e.get("type") or "")
        idx = e.get("i", k)
        t = e.get("t")
        t = int(t) if isinstance(t, (int, float)) else 0
        off = e.get("off")
        ln = e.get("len")
        off = int(off) if isinstance(off, (int, float)) else None
        ln = int(ln) if isinstance(ln, (int, float)) else None
        sid = e.get("sid")
        ev.append({"i": idx, "t": t, "node": str(e.get("node")), "type": typ,
                   "off": off, "len": ln, "sid": sid if sid else None})
    ev.sort(key=lambda x: (x["t"], 0 if x["type"] == "open" else 1))
    for e in ev:
        ty = e["type"]
        o = e["off"]
        if ty == "open":
            e["s"], e["en"] = None, 0
        elif ty == "write":
            o = o or 0
            e["s"], e["en"] = o, o + (e["len"] or 0)
        elif ty in ("checkpoint", "commit", "recover"):
            e["s"], e["en"] = o, o
        else:
            e["s"], e["en"] = None, None
    state["ev"] = ev
    return state


def _fallback(state):
    ev = state.get("ev") or []
    sids = []
    for e in ev:
        if e.get("sid") and e.get("sid") not in sids and e.get("type") != "crash":
            sids.append(e["sid"])
    first = sids[0] if sids else "s0"
    assign = {}
    for e in ev:
        if e.get("type") != "crash" and not e.get("sid"):
            assign[str(e.get("i"))] = first
    sess = {}
    for s in sids:
        sess[s] = {"status": "active", "durable": 0}
    return {"assignments": assign, "sessions": sess}


def solve_chains(state, params):
    try:
        out = _solve(state)
    except Exception:
        out = _fallback(state)
    state["output"] = out
    state.pop("ev", None)
    return state


def _solve(state):
    t0 = time.process_time()
    ev = state["ev"]
    n = len(ev)
    crashes = defaultdict(list)
    for e in ev:
        if e["type"] == "crash":
            crashes[e["node"]].append(e["t"])
    for k in crashes:
        crashes[k].sort()

    def crash_in(node, a, b):
        L = crashes.get(node)
        if not L:
            return False
        k = bisect.bisect_right(L, a)
        return k < len(L) and L[k] < b

    ts_all = [e["t"] for e in ev] or [0]
    span = max(1, max(ts_all) - min(ts_all))
    nsess = max(1, sum(1 for e in ev if e["type"] == "open"))
    nsev = max(1, sum(1 for e in ev if e["type"] != "crash"))
    g = max(1.0, span * nsess / float(nsev))

    # jitter estimate from labelled same-session offset inversions
    J = 0
    lab = defaultdict(list)
    for e in ev:
        if e["sid"] and e["type"] in ("write", "checkpoint", "commit"):
            lab[e["sid"]].append(e)
    for L in lab.values():
        L.sort(key=lambda x: x["t"])
        for a in range(len(L)):
            x = L[a]
            if x["s"] is None:
                continue
            for b in range(a + 1, min(len(L), a + 8)):
                y = L[b]
                if y["s"] is None or y["en"] is None:
                    continue
                if y["en"] <= x["s"] and y["s"] < x["s"]:
                    if crash_in(x["node"], x["t"] - 40, y["t"] + 1) or crash_in(y["node"], x["t"] - 40, y["t"] + 1):
                        continue
                    J = max(J, y["t"] - x["t"])
    J = max(2, min(12, J + 1))

    # ---------------- duplicates ----------------
    DW = max(15, 3 * J)
    dup_of = {}
    has_dup = set()
    last_by_key = defaultdict(list)
    for k, e in enumerate(ev):
        if e["type"] in ("open", "crash"):
            continue
        key = (e["node"], e["type"], e["off"], e["len"])
        best = None
        for p in reversed(last_by_key[key]):
            pe = ev[p]
            if e["t"] - pe["t"] > DW:
                break
            if p in has_dup or p in dup_of:
                continue
            if e["sid"] and pe["sid"] and e["sid"] != pe["sid"]:
                continue
            best = p
            break
        if best is not None:
            dup_of[k] = best
            has_dup.add(best)
        last_by_key[key].append(k)

    act = [k for k in range(n) if ev[k]["type"] != "crash" and k not in dup_of]
    pred_types = ("open", "write", "checkpoint", "recover")
    preds = [k for k in act if ev[k]["type"] in pred_types]
    succs = [k for k in act if ev[k]["type"] != "open"]
    by_start = defaultdict(list)
    recs = []
    aborts_by_node = defaultdict(list)
    for k in succs:
        e = ev[k]
        if e["type"] == "recover":
            recs.append(k)
        elif e["type"] == "abort":
            aborts_by_node[e["node"]].append(k)
        elif e["s"] is not None:
            by_start[e["s"]].append(k)

    def tcost(u, v):
        dt = ev[v]["t"] - ev[u]["t"]
        if dt >= 0:
            return 0.15 * dt / g
        return 0.3 * (-dt) / J + 0.05

    def lab_adj(u, v):
        a, b = ev[u]["sid"], ev[v]["sid"]
        if a and b:
            return None if a != b else -1.0
        return 0.0

    def link_cost(u, v, relaxed):
        eu, evv = ev[u], ev[v]
        if evv["t"] < eu["t"] - J:
            return None
        la = lab_adj(u, v)
        if la is None:
            return None
        tu, tv = eu["t"], evv["t"]
        uen = eu["en"]
        durable_type = eu["type"] in ("open", "checkpoint", "recover")
        vt = evv["type"]
        if vt == "recover":
            if not crash_in(eu["node"], tu - J, tv + J):
                if not relaxed:
                    return None
                c = 5.0
            else:
                c = 0.5
            if evv["off"] is None or uen is None or evv["off"] > uen:
                if not relaxed:
                    return None
                c += 3.0
            elif durable_type and evv["off"] == uen:
                c -= 0.3
            elif evv["off"] == uen:
                c += 0.4
            return c + la + tcost(u, v)
        if vt == "abort" or evv["s"] is None:
            if evv["node"] != eu["node"]:
                if not relaxed:
                    return None
                c = 4.0
            else:
                c = 0.4 if vt == "abort" else 2.0
            if crash_in(eu["node"], tu + J, tv - J):
                c += 3.0
            return c + la + tcost(u, v)
        s = evv["s"]
        if uen is None:
            if not relaxed:
                return None
            return 6.0 + la + tcost(u, v)
        definite_crash = crash_in(eu["node"], tu + J, tv - J)
        any_crash = crash_in(eu["node"], tu - J, tv + J)
        if s == uen:
            if evv["node"] == eu["node"] and not definite_crash:
                c = 0.0
            elif any_crash and durable_type:
                c = 2.5
            elif any_crash:
                if not relaxed:
                    return None
                c = 3.5
            elif relaxed:
                c = 6.0
            else:
                return None
        elif not relaxed:
            return None
        elif s > uen:
            c = 2.5 if (evv["node"] == eu["node"] and not definite_crash) else 6.0
            c += 0.2 * min(5.0, (s - uen) / 512.0)
        else:
            c = 3.0 if any_crash else 7.0
        return c + la + tcost(u, v)

    # ---------------- pass 1: exact / recover / abort links ----------------
    edges = []
    for u in preds:
        eu = ev[u]
        cand = []
        if eu["en"] is not None:
            cand.extend(by_start.get(eu["en"], ()))
        cand.extend(recs)
        cand.extend(aborts_by_node.get(eu["node"], ()))
        for v in cand:
            if v == u:
                continue
            c = link_cost(u, v, False)
            if c is not None:
                edges.append((c, u, v))
    outdeg = defaultdict(int)
    indeg = defaultdict(int)
    for c, u, v in edges:
        outdeg[u] += 1
        indeg[v] += 1
    edges = [(c + 0.05 * math.log(outdeg[u] * indeg[v]), u, v) for c, u, v in edges]
    edges.sort()

    parent = {}
    for k in act:
        parent[k] = k
    labels = {}
    for k in act:
        if ev[k]["sid"]:
            labels[k] = ev[k]["sid"]
    for k, p in dup_of.items():
        if ev[k]["sid"] and p not in labels:
            labels[p] = ev[k]["sid"]
    comp_lab = {}
    for k, s in labels.items():
        comp_lab[k] = s

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    succ = {}
    pred = {}

    def try_link(u, v):
        if u in succ or v in pred:
            return False
        ru, rv = find(u), find(v)
        if ru == rv:
            return False
        a, b = comp_lab.get(ru), comp_lab.get(rv)
        if a and b and a != b:
            return False
        parent[rv] = ru
        if (not a) and b:
            comp_lab[ru] = b
        succ[u] = v
        pred[v] = u
        return True

    for c, u, v in edges:
        try_link(u, v)

    # ---------------- pass 2: stitch fragments with gap links ----------------
    for rnd in range(2):
        hs = [k for k in act if k not in pred and ev[k]["type"] != "open"]
        tl = [k for k in act if k not in succ and ev[k]["type"] in pred_types]
        if not hs or not tl:
            break
        tl.sort(key=lambda x: ev[x]["t"])
        tl_t = [ev[x]["t"] for x in tl]
        limit = len(tl) if len(hs) * len(tl) <= 40000 else 80
        e2 = []
        for v in hs:
            hi = bisect.bisect_right(tl_t, ev[v]["t"] + J)
            lo = max(0, hi - limit)
            for j in range(lo, hi):
                u = tl[j]
                if find(u) == find(v):
                    continue
                c = link_cost(u, v, True)
                if c is not None:
                    e2.append((c, u, v))
            if time.process_time() - t0 > 0.7:
                break
        e2.sort()
        for c, u, v in e2:
            try_link(u, v)
        if time.process_time() - t0 > 0.7:
            break

    # ---------------- chains -> sessions ----------------
    opens = {}
    for k in act:
        if ev[k]["type"] == "open" and ev[k]["sid"]:
            opens[ev[k]["sid"]] = k
    sids = list(opens.keys())
    chains = {}
    for k in act:
        if k in pred:
            continue
        L = []
        x = k
        seen = 0
        while True:
            L.append(x)
            seen += 1
            if x not in succ or seen > n + 2:
                break
            x = succ[x]
        chains[k] = L
    sess_events = defaultdict(list)
    for s in sids:
        sess_events[s]
    orphan = []
    for h, L in chains.items():
        sid = None
        if ev[h]["type"] == "open" and ev[h]["sid"]:
            sid = ev[h]["sid"]
        else:
            for x in L:
                if labels.get(x):
                    sid = labels[x]
                    break
        if sid is None:
            orphan.append(L)
        else:
            sess_events[sid].append(L)

    for L in orphan:
        h = ev[L[0]]
        best, bc = None, None
        for sid, frs in sess_events.items():
            allk = [x for fr in frs for x in fr]
            before = [x for x in allk if ev[x]["t"] <= h["t"] + J]
            if not before:
                continue
            last = max(before, key=lambda x: ev[x]["t"])
            el = ev[last]
            c = max(0, h["t"] - el["t"]) / g
            if el["node"] != h["node"]:
                c += 3
            if el["type"] in ("commit", "abort") and el["t"] < h["t"] - J:
                c += 10
            if h["s"] is not None and el["en"] is not None and h["s"] != el["en"]:
                c += 1
            if bc is None or c < bc:
                best, bc = sid, c
        if best is None and sids:
            best = sids[0]
        if best is not None:
            sess_events[best].append(L)

    assign = {}
    for sid, frs in sess_events.items():
        for fr in frs:
            for x in fr:
                assign[x] = sid
    for k, p in dup_of.items():
        if p in assign:
            assign[k] = assign[p]

    def ordered(sid):
        frs = sorted(sess_events[sid],
                     key=lambda fr: (0 if ev[fr[0]]["type"] == "open" else 1, ev[fr[0]]["t"]))
        return [x for fr in frs for x in fr]

    seqs = {}
    for sid in sess_events:
        seqs[sid] = ordered(sid)

    # ---------------- duplicate repair: un-merge into exact holes of other chains ----------------
    for k, p in list(dup_of.items()):
        e = ev[k]
        if e["type"] != "write" or e["sid"] or e["s"] is None:
            continue
        own = assign.get(p)
        done = False
        for sid, seq in seqs.items():
            if sid == own:
                continue
            for a in range(len(seq) - 1):
                x, y = ev[seq[a]], ev[seq[a + 1]]
                if x["en"] is None or y["s"] is None:
                    continue
                if x["en"] == e["s"] and y["s"] == e["en"] and y["type"] != "recover" \
                        and x["node"] == e["node"] and x["t"] - J <= e["t"] <= y["t"] + J:
                    seq.insert(a + 1, k)
                    done = True
                    break
            if done:
                assign[k] = sid
                del dup_of[k]
                break

    # ---------------- final states ----------------
    sessions = {}
    all_sids = list(sess_events.keys())
    for s in sids:
        if s not in all_sids:
            all_sids.append(s)
    for sid in all_sids:
        seq = [x for x in seqs.get(sid, []) if x not in dup_of]
        if not seq:
            sessions[sid] = {"status": "active", "durable": 0}
            continue
        dur = 0
        prev = None
        status = "active"
        for x in seq:
            e = ev[x]
            ty = e["type"]
            if ty in ("checkpoint", "recover") and e["off"] is not None:
                dur = max(dur, e["off"])
            elif ty == "commit" and e["off"] is not None:
                dur = max(dur, e["off"])
            elif ty == "write" and prev is not None and prev["en"] is not None \
                    and e["s"] is not None and e["s"] < prev["en"]:
                dur = max(dur, e["s"])
            if ty == "commit":
                status = "committed"
            elif ty == "abort":
                status = "aborted"
            prev = e
        last = ev[seq[-1]]
        if last["type"] == "commit":
            d = last["off"] if last["off"] is not None else dur
            sessions[sid] = {"status": "committed", "durable": d}
            continue
        if last["type"] == "abort":
            sessions[sid] = {"status": "aborted", "durable": dur}
            continue
        if status in ("committed", "aborted"):
            sessions[sid] = {"status": status, "durable": dur}
            continue
        lo = last["t"] - J
        if last["type"] in ("recover", "open"):
            lo = last["t"]
        elif len(seq) >= 2:
            pv = ev[seq[-2]]
            if pv["en"] is not None and last["s"] is not None and last["s"] < pv["en"]:
                lo = last["t"]
            lo = max(lo, pv["t"])
        L = crashes.get(last["node"], [])
        down = bool(L) and L[-1] > lo
        sessions[sid] = {"status": "down" if down else "active", "durable": dur}

    out_assign = {}
    for k, e in enumerate(ev):
        if e["type"] == "crash" or e["sid"]:
            continue
        sid = assign.get(k)
        if sid is None:
            sid = sids[0] if sids else "s0"
        out_assign[str(e["i"])] = sid
    return {"assignments": out_assign, "sessions": sessions}

import time
import math
import random

T_OPEN, T_WRITE, T_CKPT, T_COMMIT, T_ABORT, T_RECOVER, T_CRASH = 0, 1, 2, 3, 4, 5, 6
TYPE_CODE = {"open": 0, "write": 1, "checkpoint": 2, "commit": 3, "abort": 4, "recover": 5, "crash": 6}
STATUS_NAME = {0: "active", 1: "down", 2: "committed", 3: "aborted"}


def _to_int(x):
    if x is None:
        return None
    try:
        return int(x)
    except Exception:
        try:
            return int(float(x))
        except Exception:
            return None


def _parse(inp):
    raw = inp.get("events", []) if isinstance(inp, dict) else []
    evs = []
    for k, e in enumerate(raw):
        if not isinstance(e, dict):
            continue
        tc = TYPE_CODE.get(str(e.get("type", "")).strip().lower())
        if tc is None:
            continue
        idx = _to_int(e.get("i"))
        if idx is None:
            idx = k
        t = _to_int(e.get("t"))
        if t is None:
            t = k
        sid = e.get("sid")
        if sid is not None:
            sid = str(sid)
        evs.append({"i": idx, "t": t, "node": str(e.get("node")), "type": tc,
                    "off": _to_int(e.get("off")), "len": _to_int(e.get("len")), "sid": sid, "k": k})
    evs.sort(key=lambda d: (d["t"], d["k"]))
    return evs


def _estimate_window(evs, sess_of):
    # jitter scale from known-sid write chains appearing inverted in the log
    by = {}
    for p, e in enumerate(evs):
        s = sess_of[p]
        if s is not None and e["type"] in (T_WRITE, T_CKPT, T_COMMIT) and e["off"] is not None:
            by.setdefault(s, []).append(p)
    inv = 0
    for s, lst in by.items():
        ends = {}
        for p in lst:
            e = evs[p]
            if e["type"] == T_WRITE and e["len"] is not None:
                ends.setdefault((e["node"], e["off"] + e["len"]), []).append(p)
        for p in lst:
            e = evs[p]
            for q in ends.get((e["node"], e["off"]), []):
                d = evs[q]["t"] - e["t"]
                if 0 < d <= 40 and d > inv:
                    inv = d
    gaps = [evs[k + 1]["t"] - evs[k]["t"] for k in range(len(evs) - 1)]
    gaps.sort()
    med = gaps[len(gaps) // 2] if gaps else 1
    w = max(inv + 1, 2 * med, 3)
    return min(w, 60)


def solve(state, params):
    t0 = time.process_time()
    p0 = time.perf_counter()
    BUDGET = 0.8
    PULL = 0
    inp = state.get("input", {})
    evs = _parse(inp)
    n = len(evs)

    # sessions
    sess_ids = []
    open_pos = {}
    for p, e in enumerate(evs):
        if e["type"] == T_OPEN and e["sid"] is not None and e["sid"] not in open_pos:
            open_pos[e["sid"]] = p
            sess_ids.append(e["sid"])
    for e in evs:  # sids without an open event (robustness)
        if e["sid"] is not None and e["type"] != T_CRASH and e["sid"] not in open_pos:
            open_pos[e["sid"]] = -1
            sess_ids.append(e["sid"])
    S = len(sess_ids)
    sidx = {s: k for k, s in enumerate(sess_ids)}

    node_ids = {}
    for e in evs:
        if e["node"] not in node_ids:
            node_ids[e["node"]] = len(node_ids)

    T = [e["t"] for e in evs]
    TY = [e["type"] for e in evs]
    ND = [node_ids[e["node"]] for e in evs]
    OF = [e["off"] if e["off"] is not None else -1 for e in evs]
    LN = [e["len"] if e["len"] is not None else 0 for e in evs]
    crash_pos = [p for p in range(n) if TY[p] == T_CRASH]

    sess_of = [None] * n
    anon = []
    for p, e in enumerate(evs):
        if e["type"] == T_CRASH:
            continue
        if e["sid"] is not None:
            sess_of[p] = sidx[e["sid"]]
        else:
            anon.append(p)
    if S == 0:
        state["output"] = {"assignments": {}, "sessions": {}}
        return state
    W = _estimate_window(evs, sess_of)
    OPEN = [open_pos[s] for s in sess_ids]
    OPEN_NODE = [ND[OPEN[k]] if OPEN[k] >= 0 else -1 for k in range(S)]
    nc = len(crash_pos)
    crash_start = []
    for k in range(S):
        c = 0
        while c < nc and crash_pos[c] < OPEN[k]:
            c += 1
        crash_start.append(c)

    # ---------------- replay ----------------
    def replay(k, plist, want_final=False):
        """Violation score of session k given its sorted event positions (open excluded).
        Events are replayed in log order, but an event that fits the current state exactly
        may be pulled forward from within the jitter window W (swap tolerance)."""
        op = OPEN[k]
        items = []
        ci = crash_start[k]
        last = plist[-1] if plist else op
        lim_t = (T[last] if last >= 0 else 0) + W
        for p in plist:
            while ci < nc and crash_pos[ci] < p:
                items.append(crash_pos[ci])
                ci += 1
            items.append(p)
        while ci < nc and T[crash_pos[ci]] <= lim_t:
            items.append(crash_pos[ci])
            ci += 1
        m = len(items)
        used = [False] * m
        st = 0  # 0 active, 1 down, 2 committed, 3 aborted
        node = OPEN_NODE[k]
        cur = 0
        dur = 0
        cost = 0
        seen = set()
        first = 0
        while True:
            while first < m and used[first]:
                first += 1
            if first >= m:
                break
            u = items[first]
            tu = T[u] + W
            tyu = TY[u]
            chosen = -1
            if tyu == 6:
                if st == 0 and ND[u] == node:
                    j = first + 1
                    while j < m:
                        q = items[j]
                        if T[q] > tu:
                            break
                        if not used[j]:
                            tq = TY[q]
                            if tq != 6 and tq != 5 and ND[q] == node and (tq == 4 or OF[q] == cur):
                                chosen = j
                                break
                        j += 1
                if chosen >= 0:
                    cost += PULL
                if chosen < 0:
                    used[first] = True
                    if st == 0 and ND[u] == node:
                        st = 1
                        cur = dur
                    continue
                fit = True
            else:
                if tyu == 5:
                    fit = st == 1 and OF[u] == dur
                else:
                    fit = st == 0 and (node < 0 or ND[u] == node) and (tyu == 4 or OF[u] == cur)
                if fit:
                    chosen = first
                else:
                    j = first + 1
                    while j < m:
                        q = items[j]
                        if T[q] > tu:
                            break
                        if not used[j]:
                            tq = TY[q]
                            if tq == 6:
                                if st == 0 and ND[q] == node and tyu == 5 and OF[u] == dur:
                                    chosen = j
                                    break
                            elif tq == 5:
                                if st == 1 and OF[q] == dur:
                                    chosen = j
                                    break
                            elif st == 0 and (node < 0 or ND[q] == node) and (tq == 4 or OF[q] == cur):
                                chosen = j
                                break
                        j += 1
                    if chosen < 0:
                        chosen = first
                    else:
                        fit = True
                        cost += PULL
            used[chosen] = True
            q = items[chosen]
            ty = TY[q]
            if ty == 6:
                if st == 0 and ND[q] == node:
                    st = 1
                    cur = dur
                continue
            key = (ty, ND[q], OF[q], LN[q])
            if fit:
                seen.add(key)
                if ty == 1:
                    cur = OF[q] + LN[q]
                elif ty == 2:
                    dur = cur
                elif ty == 3:
                    dur = cur
                    st = 2
                elif ty == 4:
                    cur = dur
                    st = 3
                else:
                    st = 0
                    node = ND[q]
                    cur = dur
                continue
            if key in seen:
                continue  # duplicate copy of an applied event
            seen.add(key)
            if st >= 2:
                cost += 4
                continue
            o = OF[q]
            if ty == 5:
                if st == 0:
                    cost += 3
                if o > dur:
                    cost += 1
                elif o < dur:
                    cost += 3
                st = 0
                node = ND[q]
                cur = dur = o
                continue
            if st == 1:
                cost += 1  # missing recover
                st = 0
                node = ND[q]
                cur = dur
            elif node < 0:
                node = ND[q]
            elif ND[q] != node:
                cost += 3
            if ty == 4:
                st = 3
                cur = dur
                continue
            if o > cur:
                cost += 1
            elif o < cur:
                cost += 3
            if ty == 1:
                cur = o + LN[q]
            else:
                cur = dur = o
                if ty == 3:
                    st = 2
        if want_final:
            return cost, st, dur
        return cost

    # ---------------- greedy initial labelling ----------------
    gst = [0] * S
    gnode = list(OPEN_NODE)
    gcur = [0] * S
    gdur = [0] * S
    glast = [T[OPEN[k]] if OPEN[k] >= 0 else -10 ** 9 for k in range(S)]
    gseen = [set() for _ in range(S)]
    opened = [OPEN[k] < 0 for k in range(S)]
    lists = [[] for _ in range(S)]

    def gcost(k, p):
        ty = TY[p]
        key = (ty, ND[p], OF[p], LN[p])
        if key in gseen[k]:
            return 0.5
        st = gst[k]
        o = OF[p]
        if st >= 2:
            return 6
        if ty == T_RECOVER:
            if st != 1:
                return 5
            return 0 if o == gdur[k] else (1 if o > gdur[k] else 4)
        c = 0
        cur = gcur[k]
        if st == 1:
            c += 1.5
            cur = gdur[k]
        elif gnode[k] >= 0 and ND[p] != gnode[k]:
            c += 4
        if ty == T_ABORT:
            return c + 0.2
        if o == cur:
            return c
        return c + (1 if o > cur else 4)

    def gapply(k, p):
        ty = TY[p]
        key = (ty, ND[p], OF[p], LN[p])
        glast[k] = T[p]
        if key in gseen[k]:
            return
        gseen[k].add(key)
        if gst[k] >= 2:
            return
        o = OF[p]
        if ty == T_RECOVER:
            gst[k] = 0
            gnode[k] = ND[p]
            gcur[k] = gdur[k] = o
            return
        if gst[k] == 1:
            gst[k] = 0
            gnode[k] = ND[p]
            gcur[k] = gdur[k]
        if ty == T_WRITE:
            gcur[k] = o + LN[p]
        elif ty == T_CKPT:
            gcur[k] = gdur[k] = o
        elif ty == T_COMMIT:
            gcur[k] = gdur[k] = o
            gst[k] = 2
        elif ty == T_ABORT:
            gcur[k] = gdur[k]
            gst[k] = 3

    label = list(sess_of)
    for p in range(n):
        ty = TY[p]
        if ty == T_CRASH:
            for k in range(S):
                if opened[k] and gst[k] == 0 and gnode[k] == ND[p]:
                    gst[k] = 1
                    gcur[k] = gdur[k]
            continue
        if ty == T_OPEN:
            k = sess_of[p]
            if k is not None and OPEN[k] == p:
                opened[k] = True
            elif k is not None:
                lists[k].append(p)
            continue
        if sess_of[p] is not None:
            k = sess_of[p]
        else:
            best = None
            for kk in range(S):
                if not opened[kk]:
                    continue
                c = gcost(kk, p)
                key = (c, T[p] - glast[kk], kk)
                if best is None or key < best[0]:
                    best = (key, kk)
            if best is None:
                k = min(range(S), key=lambda kk: (OPEN[kk], kk))
            else:
                k = best[1]
            label[p] = k
        lists[k].append(p)
        gapply(k, p)

    # ---------------- local search ----------------
    scores = [replay(k, lists[k]) if S else 0 for k in range(S)]

    def cands(p):
        out = []
        for k in range(S):
            if OPEN[k] < p:
                out.append(k)
        return out

    cand_cache = {p: cands(p) for p in anon}

    def with_added(lst, p):
        res = list(lst)
        lo, hi = 0, len(res)
        while lo < hi:
            mid = (lo + hi) // 2
            if res[mid] < p:
                lo = mid + 1
            else:
                hi = mid
        res.insert(lo, p)
        return res

    def with_removed(lst, p):
        res = list(lst)
        res.remove(p)
        return res

    def time_left():
        return (time.process_time() - t0) < BUDGET and (time.perf_counter() - p0) < BUDGET * 1.6

    # quick plausibility prefilter: sessions whose offsets connect to the event
    def related(k, p, lst):
        ty = TY[p]
        o = OF[p]
        if ty == T_ABORT:
            return True
        if o == 0:
            return True
        endp = o + LN[p] if ty == T_WRITE else o
        for q in lst:
            tq = TY[q]
            if tq == T_WRITE:
                e = OF[q] + LN[q]
                if e == o or OF[q] == endp:
                    return True
            elif tq in (T_CKPT, T_RECOVER, T_COMMIT):
                if OF[q] == o or OF[q] == endp:
                    return True
        return False

    def anon_run(lst, p):
        j = lst.index(p)
        lo = j
        while lo > 0 and sess_of[lst[lo - 1]] is None:
            lo -= 1
        hi = j
        while hi + 1 < len(lst) and sess_of[lst[hi + 1]] is None:
            hi += 1
        return lo, hi, j

    def try_block(a, blk, k):
        # returns (delta, la, sa, lb, sb) for moving the event block blk from a to k
        if OPEN[k] > blk[0]:
            return None
        bs = set(blk)
        la = [q for q in lists[a] if q not in bs]
        lb = sorted(lists[k] + blk)
        sa = replay(a, la)
        sb = replay(k, lb)
        return (sa + sb - scores[a] - scores[k], la, sa, lb, sb)

    rng = random.Random(12345)
    order = list(anon)

    # swap buckets: anonymous events with identical (type, off)
    buckets = {}
    for p in anon:
        buckets.setdefault((TY[p], OF[p]), []).append(p)
    bucket_list = [v for v in buckets.values() if len(v) > 1]

    improved = True
    sweeps = 0
    while improved and time_left():
        improved = False
        sweeps += 1
        rng.shuffle(order)
        for p in order:
            if not time_left():
                break
            a = label[p]
            la = lists[a]
            a_wo = None
            best_d = 0
            best_k = -1
            best_vals = None
            cl = cand_cache[p]
            rel = [k for k in cl if k != a and related(k, p, lists[k])]
            if not rel and sweeps > 1:
                continue
            if not rel:
                rel = [k for k in cl if k != a]
            for k in rel:
                if a_wo is None:
                    a_without_list = with_removed(la, p)
                    a_wo = replay(a, a_without_list)
                    if a_wo >= scores[a]:
                        break  # event costs nothing where it is
                lb = with_added(lists[k], p)
                sb = replay(k, lb)
                d = (a_wo - scores[a]) + (sb - scores[k])
                if d < best_d:
                    best_d = d
                    best_k = k
                    best_vals = (a_without_list, a_wo, lb, sb)
            if best_k >= 0:
                lists[a] = best_vals[0]
                scores[a] = best_vals[1]
                lists[best_k] = best_vals[2]
                scores[best_k] = best_vals[3]
                label[p] = best_k
                improved = True
        # swap moves
        for b in bucket_list:
            if not time_left():
                break
            m = len(b)
            for x in range(m):
                for y in range(x + 1, m):
                    p1, p2 = b[x], b[y]
                    a1, a2 = label[p1], label[p2]
                    if a1 == a2:
                        continue
                    if OPEN[a1] > p2 or OPEN[a2] > p1:
                        continue
                    l1 = with_added(with_removed(lists[a1], p1), p2)
                    l2 = with_added(with_removed(lists[a2], p2), p1)
                    s1 = replay(a1, l1)
                    s2 = replay(a2, l2)
                    if s1 + s2 < scores[a1] + scores[a2]:
                        lists[a1], lists[a2] = l1, l2
                        scores[a1], scores[a2] = s1, s2
                        label[p1], label[p2] = a2, a1
                        improved = True
                        continue
                    # suffix swap: exchange every anonymous event from p1 / p2 onwards
                    m1 = [q for q in lists[a1] if q >= p1 and sess_of[q] is None]
                    m2 = [q for q in lists[a2] if q >= p2 and sess_of[q] is None]
                    if len(m1) + len(m2) <= 2:
                        continue
                    if (m2 and OPEN[a1] > m2[0]) or (m1 and OPEN[a2] > m1[0]):
                        continue
                    s1m = set(m1)
                    s2m = set(m2)
                    l1 = sorted([q for q in lists[a1] if q not in s1m] + m2)
                    l2 = sorted([q for q in lists[a2] if q not in s2m] + m1)
                    s1 = replay(a1, l1)
                    s2 = replay(a2, l2)
                    if s1 + s2 < scores[a1] + scores[a2]:
                        lists[a1], lists[a2] = l1, l2
                        scores[a1], scores[a2] = s1, s2
                        for q in m1:
                            label[q] = a2
                        for q in m2:
                            label[q] = a1
                        improved = True
        # block moves: move a run of consecutive anonymous events (whole run, or a prefix/suffix)
        for a in range(S):
            if not time_left():
                break
            lst = lists[a]
            x = 0
            runs = []
            while x < len(lst):
                if sess_of[lst[x]] is None:
                    y = x
                    while y + 1 < len(lst) and sess_of[lst[y + 1]] is None:
                        y += 1
                    if y > x:
                        runs.append(lst[x:y + 1])
                    x = y + 1
                else:
                    x += 1
            for run in runs:
                if not time_left():
                    break
                blocks = [run]
                L = len(run)
                if L > 2:
                    for c in range(1, min(L, 6)):
                        blocks.append(run[:c + 1] if c + 1 < L else run[:c])
                        blocks.append(run[L - c - 1:] if L - c - 1 > 0 else run[1:])
                bestm = None
                for blk in blocks:
                    if label[blk[0]] != a:
                        continue
                    for k in cand_cache[blk[0]]:
                        if k == a or not related(k, blk[0], lists[k]):
                            continue
                        r = try_block(a, blk, k)
                        if r is not None and r[0] < 0 and (bestm is None or r[0] < bestm[0][0]):
                            bestm = (r, blk, k)
                if bestm is not None:
                    r, blk, k = bestm
                    lists[a], scores[a], lists[k], scores[k] = r[1], r[2], r[3], r[4]
                    for q in blk:
                        label[q] = k
                    improved = True
                    break
        if not time_left():
            break

    # ---------------- simulated annealing with best tracking ----------------
    cur_total = sum(scores)
    best_total = cur_total
    best_label = list(label)
    best_lists = [list(l) for l in lists]
    best_scores = list(scores)
    if anon and S > 1 and time_left():
        T0 = 1.2
        temp = T0
        it = 0
        na = len(anon)
        nb = len(bucket_list)
        while True:
            if (it & 15) == 0:
                if not time_left():
                    break
                el = time.process_time() - t0
                frac = min(1.0, max(0.0, el / BUDGET))
                temp = T0 * (1.0 - frac) + 0.05
            it += 1
            rmv = rng.random()
            if rmv < 0.25:
                p = anon[rng.randrange(na)]
                a = label[p]
                lo, hi, j = anon_run(lists[a], p)
                if hi == lo:
                    continue
                x1 = rng.randint(lo, j)
                x2 = rng.randint(j, hi)
                if x1 == x2:
                    continue
                blk = lists[a][x1:x2 + 1]
                cl = cand_cache[blk[0]]
                if not cl:
                    continue
                k = cl[rng.randrange(len(cl))]
                if k == a:
                    continue
                r = try_block(a, blk, k)
                if r is None:
                    continue
                d = r[0]
                if d <= 0 or rng.random() < math.exp(-d / temp):
                    lists[a], scores[a], lists[k], scores[k] = r[1], r[2], r[3], r[4]
                    for q in blk:
                        label[q] = k
                    cur_total += d
            elif rmv < 0.45:
                # window swap: exchange all anonymous events of two sessions inside [p, p2]
                p = anon[rng.randrange(na)]
                a = label[p]
                cl = cand_cache[p]
                if not cl:
                    continue
                k = cl[rng.randrange(len(cl))]
                if k == a:
                    continue
                if rng.random() < 0.5:
                    p2 = n
                else:
                    p2 = p + rng.randint(1, 60)
                ma = [q for q in lists[a] if p <= q <= p2 and sess_of[q] is None]
                mb = [q for q in lists[k] if p <= q <= p2 and sess_of[q] is None]
                if not mb or (OPEN[a] > mb[0]):
                    continue
                sa_set = set(ma)
                sb_set = set(mb)
                la = sorted([q for q in lists[a] if q not in sa_set] + mb)
                lb = sorted([q for q in lists[k] if q not in sb_set] + ma)
                sa = replay(a, la)
                sb = replay(k, lb)
                d = sa + sb - scores[a] - scores[k]
                if d <= 0 or rng.random() < math.exp(-d / temp):
                    lists[a], scores[a], lists[k], scores[k] = la, sa, lb, sb
                    for q in ma:
                        label[q] = k
                    for q in mb:
                        label[q] = a
                    cur_total += d
            elif nb and rmv < 0.6:
                b = bucket_list[rng.randrange(nb)]
                p1 = b[rng.randrange(len(b))]
                p2 = b[rng.randrange(len(b))]
                a1, a2 = label[p1], label[p2]
                if a1 == a2 or OPEN[a1] > p2 or OPEN[a2] > p1:
                    continue
                l1 = with_added(with_removed(lists[a1], p1), p2)
                l2 = with_added(with_removed(lists[a2], p2), p1)
                s1 = replay(a1, l1)
                s2 = replay(a2, l2)
                d = s1 + s2 - scores[a1] - scores[a2]
                if d <= 0 or rng.random() < math.exp(-d / temp):
                    lists[a1], lists[a2] = l1, l2
                    scores[a1], scores[a2] = s1, s2
                    label[p1], label[p2] = a2, a1
                    cur_total += d
            else:
                p = anon[rng.randrange(na)]
                cl = cand_cache[p]
                if len(cl) < 2:
                    continue
                a = label[p]
                k = cl[rng.randrange(len(cl))]
                if k == a:
                    continue
                if rng.random() < 0.8 and not related(k, p, lists[k]):
                    continue
                la = with_removed(lists[a], p)
                lb = with_added(lists[k], p)
                sa = replay(a, la)
                sb = replay(k, lb)
                d = sa + sb - scores[a] - scores[k]
                if d <= 0 or rng.random() < math.exp(-d / temp):
                    lists[a], lists[k] = la, lb
                    scores[a], scores[k] = sa, sb
                    label[p] = k
                    cur_total += d
            if cur_total < best_total:
                best_total = cur_total
                best_label = list(label)
                best_lists = [list(l) for l in lists]
                best_scores = list(scores)
        label = best_label
        lists = best_lists
        scores = best_scores

    # ---------------- output ----------------
    assignments = {}
    for p in anon:
        k = label[p]
        if k is not None and 0 <= k < S:
            assignments[str(evs[p]["i"])] = sess_ids[k]
    sessions = {}
    for k in range(S):
        c, st, dur = replay(k, lists[k], True)
        sessions[sess_ids[k]] = {"status": STATUS_NAME[st], "durable": int(dur)}
    state["output"] = {"assignments": assignments, "sessions": sessions}
    return state


def solve_safe(state, params):
    try:
        return solve(state, params if isinstance(params, dict) else {})
    except Exception:
        inp = state.get("input", {}) if isinstance(state, dict) else {}
        evs = inp.get("events", []) if isinstance(inp, dict) else []
        assignments = {}
        sessions = {}
        last_sid = None
        for e in evs:
            if not isinstance(e, dict):
                continue
            sid = e.get("sid")
            ty = e.get("type")
            if sid is not None:
                sid = str(sid)
                sessions.setdefault(sid, {"status": "active", "durable": 0})
                last_sid = sid
            elif ty != "crash" and last_sid is not None:
                assignments[str(e.get("i"))] = last_sid
        state["output"] = {"assignments": assignments, "sessions": sessions}
        return state

import time
import random
import bisect

TCODE = {"write": 0, "checkpoint": 1, "commit": 2, "abort": 3, "recover": 4, "open": 5, "crash": 6}
C_NODE = 2.0
C_GAP = 1.0
C_BACK = 3.0
C_MISSREC = 1.0
C_AFTEREND = 6.0
C_DUP = 0.15
C_BEFOREOPEN = 6.0
C_RECACTIVE = 3.0


def _apply(st, ty, node, off, ln):
    # st = (status, node, cur, dur); status 0 active,1 down,2 committed,3 aborted
    s, nd, cur, dur = st
    if ty == 6:
        if s == 0 and nd == node:
            return 0.0, (1, nd, dur, dur)
        return 0.0, st
    if s >= 2:
        return C_AFTEREND, st
    cost = 0.0
    if ty == 4:
        if s == 0:
            cost += C_RECACTIVE
        base = dur
        if off is None:
            off = base
        if off > base:
            cost += C_GAP * 0.5
        elif off < base:
            cost += C_BACK
        return cost, (0, node, off, off)
    if s == 1:
        cost += C_MISSREC
        s = 0
        cur = dur
        nd = node
    elif nd != node:
        cost += C_NODE
        nd = node
    if ty == 3:
        return cost, (3, nd, dur, dur)
    if off is None:
        off = cur
    if off > cur:
        cost += C_GAP
    elif off < cur:
        cost += C_BACK
    if ty == 0:
        return cost, (0, nd, off + (ln or 0), dur)
    if ty == 1:
        return cost, (0, nd, off, off)
    return cost, (2, nd, off, off)


def _replay(items, onode, ot, W, want_state=False, tend=None, g=None, eps=0.0):
    # items: list of (t, ty, node, off, len, sig) sorted by t (session events + crashes after open)
    n = len(items)
    used = [False] * n
    st = (0, onode, 0, 0)
    seen = set()
    total = 0.0
    head = 0
    done = 0
    lastt = ot
    while done < n:
        while used[head]:
            head += 1
        lim = items[head][0] + W
        best = None
        bc = 1e18
        j = head
        cnt = 0
        while j < n and items[j][0] <= lim and cnt < 10:
            if not used[j]:
                it = items[j]
                ty = it[1]
                if ty != 6 and it[5] in seen:
                    c = C_DUP
                    ns = st
                else:
                    c, ns = _apply(st, ty, it[2], it[3], it[4])
                    if ty != 6 and it[0] < ot:
                        c += C_BEFOREOPEN
                key = c + (0.001 if ty == 6 else 0.0) + 0.0001 * cnt
                if key < bc:
                    bc = key
                    best = (j, c, ns)
                cnt += 1
            j += 1
        j, c, ns = best
        used[j] = True
        done += 1
        total += c
        st = ns
        it = items[j]
        if it[1] != 6:
            seen.add(it[5])
            if eps:
                dt = it[0] - lastt
                if dt > 0:
                    total += eps * min(dt / g, 6.0)
                    lastt = it[0]
    if tend is not None and st[0] == 0:
        tl = ot
        for it in items:
            if it[1] != 6 and it[0] > tl:
                tl = it[0]
        sil = tend - tl
        if sil > 3 * g:
            total += min(1.2, (sil - 3 * g) / (4.0 * g))
    if want_state:
        return total, st
    return total


def solve(state, params):
    t_start = time.perf_counter()
    inp = state.get("input") or {}
    evs = inp.get("events") or []
    nodes = list(inp.get("nodes") or [])
    E = []
    for e in evs:
        try:
            idx = int(e.get("i"))
        except Exception:
            continue
        ty = TCODE.get(e.get("type"), -1)
        if ty < 0:
            continue
        t = e.get("t")
        try:
            t = int(t)
        except Exception:
            t = 0
        off = e.get("off")
        ln = e.get("len")
        off = int(off) if isinstance(off, (int, float)) else None
        ln = int(ln) if isinstance(ln, (int, float)) else None
        nd = e.get("node")
        if nd not in nodes:
            nodes.append(nd)
        E.append({"i": idx, "t": t, "ty": ty, "node": nd, "off": off, "len": ln, "sid": e.get("sid")})
    E.sort(key=lambda x: (x["t"], x["i"]))
    nidx = {n: k for k, n in enumerate(nodes)}
    for x in E:
        x["n"] = nidx[x["node"]]
    sess = []
    sid_of = {}
    opens = {}
    for x in E:
        if x["ty"] == 5 and x["sid"] is not None and x["sid"] not in opens:
            opens[x["sid"]] = x
            sid_of[x["sid"]] = len(sess)
            sess.append(x["sid"])
    for x in E:
        if x["ty"] not in (5, 6) and x["sid"] is not None and x["sid"] not in sid_of:
            sid_of[x["sid"]] = len(sess)
            sess.append(x["sid"])
            opens[x["sid"]] = {"t": x["t"], "n": x["n"], "ty": 5}
    S = len(sess)
    crashes = [(x["t"], x["n"]) for x in E if x["ty"] == 6]
    ev_items = []
    for x in E:
        ev_items.append((x["t"], x["ty"], x["n"], x["off"], x["len"], (x["ty"], x["n"], x["off"], x["len"])))
    anon = [k for k, x in enumerate(E) if x["ty"] not in (5, 6) and x["sid"] is None]
    fixed = [k for k, x in enumerate(E) if x["ty"] not in (5, 6) and x["sid"] is not None]
    if S == 0:
        state["output"] = {"assignments": {}, "sessions": {}}
        return state

    # ---- jitter window estimate from labelled sessions
    crash_ts = [c[0] for c in crashes]
    est = 0
    lab = {}
    for k in fixed:
        lab.setdefault(E[k]["sid"], []).append(k)
    for s, ks in lab.items():
        for a in range(len(ks)):
            xa = E[ks[a]]
            if xa["ty"] not in (0, 1, 2):
                continue
            sa = xa["off"] if xa["off"] is not None else 0
            for b in range(a + 1, len(ks)):
                xb = E[ks[b]]
                if xb["t"] - xa["t"] > 60:
                    break
                if xb["ty"] not in (0, 1) or xb["off"] is None:
                    continue
                eb = xb["off"] + (xb["len"] or 0) if xb["ty"] == 0 else xb["off"]
                if eb <= sa and (xb["ty"] == 0 and eb < sa + 1 or xb["ty"] == 1 and eb < sa):
                    p = bisect.bisect_left(crash_ts, xa["t"] - 60)
                    if p < len(crash_ts) and crash_ts[p] <= xb["t"] + 60:
                        continue
                    est = max(est, xb["t"] - xa["t"])
    W = max(int(est * 1.3) + 2, 3)

    # ---- greedy initial labelling (online, t-order)
    label = [-1] * len(E)
    for k in fixed:
        label[k] = sid_of[E[k]["sid"]]
    stt = [None] * S
    seen = [set() for _ in range(S)]
    last_t = [None] * S
    for k, x in enumerate(E):
        ty = x["ty"]
        if ty == 5:
            s = sid_of.get(x["sid"])
            if s is not None and stt[s] is None:
                stt[s] = (0, x["n"], 0, 0)
                last_t[s] = x["t"]
            continue
        if ty == 6:
            for s in range(S):
                if stt[s] is not None:
                    c, ns = _apply(stt[s], 6, x["n"], None, None)
                    stt[s] = ns
            continue
        it = ev_items[k]
        if label[k] >= 0:
            s = label[k]
            if stt[s] is None:
                stt[s] = (0, x["n"], 0, 0)
            if it[5] not in seen[s]:
                c, stt[s] = _apply(stt[s], ty, x["n"], x["off"], x["len"])
                seen[s].add(it[5])
            last_t[s] = x["t"]
            continue
        bestc = 1e18
        bs = 0
        for s in range(S):
            if stt[s] is None:
                o = opens.get(sess[s])
                if o is None or o["t"] > x["t"] + W:
                    continue
                cs = (0, o["n"], 0, 0)
            else:
                cs = stt[s]
            if it[5] in seen[s]:
                c = C_DUP
            else:
                c, _ = _apply(cs, ty, x["n"], x["off"], x["len"])
            if cs[1] != x["n"]:
                c += 0.05
            c += 0.0001 * min(1000, x["t"] - (last_t[s] if last_t[s] is not None else x["t"]))
            if c < bestc:
                bestc = c
                bs = s
        label[k] = bs
        s = bs
        if stt[s] is None:
            o = opens[sess[s]]
            stt[s] = (0, o["n"], 0, 0)
        if it[5] not in seen[s]:
            c, stt[s] = _apply(stt[s], ty, x["n"], x["off"], x["len"])
            seen[s].add(it[5])
        last_t[s] = x["t"]

    init = params.get("init")
    if init:
        for k in anon:
            label[k] = sid_of[init[str(E[k]["i"])]]
    # ---- per-session item lists
    members = [[] for _ in range(S)]
    for k in range(len(E)):
        if label[k] >= 0:
            members[label[k]].append((E[k]["t"], k))
    for s in range(S):
        members[s].sort()
    otl = [opens[sess[s]]["t"] for s in range(S)]
    onl = [opens[sess[s]]["n"] for s in range(S)]
    crash_items = [(c[0], 6, c[1], None, None, None) for c in crashes]

    def cost_of(mem, s):
        ot = otl[s]
        p = bisect.bisect_left(crash_ts, ot)
        items = [ev_items[k] for (_, k) in mem]
        if p < len(crash_items):
            items = items + crash_items[p:]
            items.sort(key=lambda z: (z[0], 1 if z[1] == 6 else 0))
        if not items:
            return 0.0
        return _replay(items, onl[s], ot, W, False, tend, gtyp, EPS)

    tend = E[-1]["t"]
    sg = []
    for s in range(S):
        prev = otl[s]
        for (tt, k) in members[s]:
            if tt > prev:
                sg.append(tt - prev)
                prev = tt
    sg.sort()
    gtyp = max(1.0, float(sg[len(sg) // 2]) if sg else 10.0)
    EPS = params.get("eps", 0.08)
    costs = [cost_of(members[s], s) for s in range(S)]
    total = sum(costs)

    # ---- local search (simulated annealing)
    budget = params.get("budget", 0.55)
    rng = random.Random(12345)
    if anon and S > 1:
        feas = []
        for k in anon:
            tk = E[k]["t"]
            f = [s for s in range(S) if otl[s] <= tk]
            if not f:
                f = list(range(S))
            feas.append(f)
        apos = {k: a for a, k in enumerate(anon)}
        bytype = {}
        for k in anon:
            bytype.setdefault(E[k]["ty"], []).append((E[k]["t"], k))
        for v in bytype.values():
            v.sort()
        SW = max(4 * W, 20)
        SEGS = [2 * W + 2 * gtyp, 6 * gtyp + 2 * W, 20 * gtyp, 1 << 40]
        isanon = [False] * len(E)
        for k in anon:
            isanon[k] = True
        node_act = [[] for _ in range(S)]
        for s in range(S):
            node_act[s].append((otl[s], onl[s]))
            for (tt, kk) in members[s]:
                node_act[s].append((tt, E[kk]["n"]))
        PW = 4 * gtyp + 2 * W
        plaus = []
        for k in anon:
            tk = E[k]["t"]
            nk = E[k]["n"]
            f = []
            for s in range(S):
                if otl[s] > tk + W:
                    continue
                for (tt, nn) in node_act[s]:
                    if nn == nk and abs(tt - tk) <= PW:
                        f.append(s)
                        break
            plaus.append(f)
        best_total = total
        best_label = label[:]
        T0, T1 = 1.0, 0.03
        it_n = 0
        temp = T0
        while True:
            if (it_n & 31) == 0:
                el = time.perf_counter() - t_start
                if el > budget:
                    break
                fr = el / budget
                temp = T0 * (T1 / T0) ** fr
            it_n += 1
            k = anon[rng.randrange(len(anon))]
            s1 = label[k]
            r = rng.random()
            if r < 0.5:
                if rng.random() < 0.7 and plaus[apos[k]]:
                    f = plaus[apos[k]]
                else:
                    f = feas[apos[k]]
                s2 = f[rng.randrange(len(f))]
                if s2 == s1:
                    continue
                m1 = [z for z in members[s1] if z[1] != k]
                m2 = members[s2][:]
                bisect.insort(m2, (E[k]["t"], k))
                c1 = cost_of(m1, s1)
                c2 = cost_of(m2, s2)
                d = c1 + c2 - costs[s1] - costs[s2]
                if d <= 0 or rng.random() < pow(2.718281828, -d / temp):
                    members[s1] = m1
                    members[s2] = m2
                    costs[s1] = c1
                    costs[s2] = c2
                    label[k] = s2
                    total += d
            elif r < 0.85:
                lst = bytype[E[k]["ty"]]
                tk = E[k]["t"]
                lo = bisect.bisect_left(lst, (tk - SW, -1))
                hi = bisect.bisect_right(lst, (tk + SW, 1 << 30))
                if hi - lo < 2:
                    continue
                k2 = lst[rng.randrange(lo, hi)][1]
                s2 = label[k2]
                if s2 == s1 or k2 == k:
                    continue
                if otl[s2] > tk or otl[s1] > E[k2]["t"]:
                    continue
                m1 = [z for z in members[s1] if z[1] != k]
                bisect.insort(m1, (E[k2]["t"], k2))
                m2 = [z for z in members[s2] if z[1] != k2]
                bisect.insort(m2, (tk, k))
                c1 = cost_of(m1, s1)
                c2 = cost_of(m2, s2)
                d = c1 + c2 - costs[s1] - costs[s2]
                if d <= 0 or rng.random() < pow(2.718281828, -d / temp):
                    members[s1] = m1
                    members[s2] = m2
                    costs[s1] = c1
                    costs[s2] = c2
                    label[k] = s2
                    label[k2] = s1
                    total += d
            else:
                f = plaus[apos[k]] or feas[apos[k]]
                s2 = f[rng.randrange(len(f))]
                if s2 == s1:
                    continue
                tk = E[k]["t"]
                D = SEGS[rng.randrange(len(SEGS))]
                ta = tk - (0 if rng.random() < 0.5 else W)
                tb = tk + D
                if otl[s2] > ta or otl[s1] > ta:
                    continue
                mv1 = [z for z in members[s1] if ta <= z[0] <= tb and isanon[z[1]]]
                mv2 = [z for z in members[s2] if ta <= z[0] <= tb and isanon[z[1]]]
                if not mv1 and not mv2:
                    continue
                st1 = set(z[1] for z in mv1)
                st2 = set(z[1] for z in mv2)
                m1 = sorted([z for z in members[s1] if z[1] not in st1] + mv2)
                m2 = sorted([z for z in members[s2] if z[1] not in st2] + mv1)
                c1 = cost_of(m1, s1)
                c2 = cost_of(m2, s2)
                d = c1 + c2 - costs[s1] - costs[s2]
                if d <= 0 or rng.random() < pow(2.718281828, -d / temp):
                    members[s1] = m1
                    members[s2] = m2
                    costs[s1] = c1
                    costs[s2] = c2
                    for z in mv1:
                        label[z[1]] = s2
                    for z in mv2:
                        label[z[1]] = s1
                    total += d
            if total < best_total - 1e-9:
                best_total = total
                best_label = label[:]
        label = best_label
        members = [[] for _ in range(S)]
        for k in range(len(E)):
            if label[k] >= 0:
                members[label[k]].append((E[k]["t"], k))
        for s in range(S):
            members[s].sort()

    # ---- final replay for statuses
    SIL_K = params.get("silk", 5.0)
    out_s = {}
    names = {0: "active", 1: "down", 2: "committed", 3: "aborted"}
    for s in range(S):
        ot = otl[s]
        p = bisect.bisect_left(crash_ts, ot)
        items = [ev_items[k] for (_, k) in members[s]] + crash_items[p:]
        items.sort(key=lambda z: (z[0], 1 if z[1] == 6 else 0))
        if items:
            _, st = _replay(items, onl[s], ot, W, True)
        else:
            st = (0, onl[s], 0, 0)
        tl = ot
        for it in items:
            if it[1] != 6 and it[0] > tl:
                tl = it[0]
        if st[0] == 0 and tend - tl > SIL_K * gtyp:
            st = (3, st[1], st[3], st[3])
        out_s[sess[s]] = {"status": names[st[0]], "durable": int(st[3])}
    asg = {}
    for k in anon:
        asg[str(E[k]["i"])] = sess[label[k]]
    state["output"] = {"assignments": asg, "sessions": out_s}
    return state

import time, bisect

KMAX = 16

def _defaults():
    return {'gap': 1.5, 'reord': 0.3, 'back': 5.0, 'fill': 0.4, 'wnode': 15.0, 'down_new': 2.5,
            'ended': 3.0, 'a_eq': 1.0, 'a_lt': 0.3, 'a_gt': 3.0, 'ac_eq': 0.7,
            'dupw': 0.2, 'dupx': 2.0, 'rec': 0.015, 'beam': 8, 'opts': 3, 'IK': 3.5, 'IA': 5.0,
            'MINN': 2, 'abort_base': 0.5, 'abort_fut': 5.0, 'abort_near': 1.0, 'dupwin': 60,
            'JW': 4, 'strag_pend': 0.3, 'strag_other': 1.5, 'commit_fut': 4.0, 'farpad': 15}

def _push(tup, v):
    if v in tup:
        return tup
    tup = tup + (v,)
    if len(tup) > KMAX:
        tup = tup[-KMAX:]
    return tup

def _run(evs, crash_pos, fut, P, beam_w):
    INF = 1e9
    order = []
    sidx = {}

    def anchor(sid, p, node):
        lst = fut.get(sid)
        if not lst:
            return None
        k = bisect.bisect_right(lst, p)
        while k < len(lst):
            q = lst[k]
            e = evs[q]
            ty = e['type']
            if ty in ('write', 'checkpoint', 'commit'):
                if e['node'] != node:
                    return None
                cp = crash_pos.get(node, ())
                j = bisect.bisect_right(cp, p)
                if j < len(cp) and cp[j] < q:
                    return None
                return e
            if ty in ('recover', 'abort'):
                return None
            k += 1
        return None

    def has_future(sid, p):
        lst = fut.get(sid)
        if not lst:
            return False
        return bisect.bisect_right(lst, p) < len(lst)

    def has_far(sid, p, t):
        lst = fut.get(sid)
        if not lst or lst[-1] <= p:
            return False
        return evs[lst[-1]]['t'] > t + P['JW'] + P['farpad']

    def is_strag(s, e):
        return s['node'] == e['node'] and s['downt'] is not None and e['t'] - s['downt'] <= P['JW']

    def fresh_cost(s, sid, e, p):
        ty = e['type']; N = e['node']; o = e['off']
        st = s['st']
        if ty == 'write':
            if o is None:
                return 5.0
            l = e['len'] or 0
            end = o + l
            if st == 'committed':
                return P['ended'] if (s['final'] is not None and end <= s['final']) else 20.0
            if st == 'aborted':
                return P['ended']
            if st == 'down':
                if is_strag(s, e):
                    c = P['strag_pend'] if o in s['pends'] else P['strag_other']
                else:
                    c = P['down_new'] + (0 if o == s['dur'] else (P['gap'] if o > s['dur'] else P['back'] + 1))
            else:
                if s['node'] != N:
                    return P['wnode']
                pos = s['pos']
                if o == pos: c = 0.0
                elif o in s['ends']: c = P['reord']
                elif o > pos: c = P['gap']
                else: c = P['back']
                if end in s['starts']: c -= P['fill']
            a = anchor(sid, p, N)
            if a is not None and a['off'] is not None:
                X = a['off']
                if a['type'] == 'write':
                    if end == X: c -= P['a_eq']
                    elif end < X: c += P['a_lt']
                    else: c += P['a_gt']
                else:
                    if end == X: c -= P['ac_eq']
                    elif end > X: c += P['a_gt']
            return c
        if ty in ('checkpoint', 'commit'):
            X = o if o is not None else s['pos']
            if st == 'committed':
                return P['ended'] if (s['final'] is not None and X <= s['final']) else 20.0
            if st == 'aborted':
                return 20.0 if ty == 'commit' else P['ended']
            if st == 'down':
                if is_strag(s, e):
                    c = P['strag_pend'] if X in s['pends'] else P['strag_other']
                elif X == s['dur']:
                    c = 3.0
                else:
                    c = 4.0
            else:
                if s['node'] != N:
                    return P['wnode']
                pos = s['pos']
                if X < s['dur']: c = 8.0
                elif X == pos: c = 0.0
                elif X in s['ends']: c = P['reord']
                elif X > pos: c = P['gap']
                else: c = 2.5
            a = anchor(sid, p, N)
            if a is not None and a['off'] is not None:
                Y = a['off']
                if X > Y: c += P['a_gt']
                elif X == Y and a['type'] == 'write': c -= 0.5
            if ty == 'commit' and has_far(sid, p, e['t']):
                c += P['commit_fut']
            return c
        if ty == 'recover':
            X = o if o is not None else s['dur']
            if st in ('committed', 'aborted'):
                return 20.0
            if st == 'down':
                if X == s['dur']: return 0.0
                if X > s['dur']: return 1.5
                return 6.0
            if X == s['dur']: return 4.0
            return 7.0
        if ty == 'abort':
            if st in ('committed', 'aborted'):
                return 20.0
            if st == 'down':
                c = P['strag_other'] if is_strag(s, e) else 4.0
            elif s['node'] != N:
                return P['wnode']
            else:
                c = P['abort_base']
            if has_far(sid, p, e['t']):
                c += P['abort_fut']
            elif has_future(sid, p):
                c += P['abort_near']
            return c
        return INF

    def apply(s, e):
        s = dict(s)
        ty = e['type']; o = e['off']
        st = s['st']
        if ty == 'write' and o is not None:
            end = o + (e['len'] or 0)
            if st == 'active':
                s['pos'] = max(s['pos'], end)
                s['ends'] = _push(s['ends'], end); s['starts'] = _push(s['starts'], o)
            elif st == 'down' and is_strag(s, e):
                s['pends'] = _push(s['pends'], end)
            elif st == 'down':
                s['st'] = 'active'; s['node'] = e['node']
                s['pos'] = max(s['dur'], end); s['ends'] = (s['dur'], end); s['starts'] = (o,)
        elif ty in ('checkpoint', 'commit') and o is not None:
            if st in ('active', 'down'):
                s['dur'] = max(s['dur'], o)
                if st == 'active':
                    s['pos'] = max(s['pos'], o); s['ends'] = _push(s['ends'], o)
                else:
                    s['pends'] = _push(s['pends'], o)
                if ty == 'commit':
                    s['st'] = 'committed'; s['final'] = o; s['node'] = e['node']
        elif ty == 'recover' and o is not None:
            if st in ('down', 'active'):
                s['dur'] = max(s['dur'], o)
                s['st'] = 'active'; s['node'] = e['node']; s['pos'] = o
                s['ends'] = (o,); s['starts'] = ()
        elif ty == 'abort':
            if st in ('active', 'down'):
                s['st'] = 'aborted'
        s['last'] = e['t']
        s['cnt'] = s['cnt'] + 1
        key = (e['node'], ty, o, e['len'])
        kl = [k for k in s['keys'] if k[2] >= e['t'] - P['dupwin']]
        kl.append((key, s['epoch'], e['t']))
        s['keys'] = tuple(kl)
        return s

    def sig_of(s):
        return (s['st'], s['node'], s['pos'], s['dur'], s['epoch'])

    hyps = [[0.0, [], (), None]]
    for p, e in enumerate(evs):
        ty = e['type']
        if ty == 'open':
            sid = e['sid']
            if sid is None or sid in sidx:
                continue
            sidx[sid] = len(order); order.append(sid)
            ns = {'st': 'active', 'node': e['node'], 'pos': 0, 'dur': 0, 'ends': (0,), 'starts': (),
                  'pends': (), 'final': None, 'last': e['t'], 'epoch': 0, 'keys': (), 'cnt': 0,
                  'first': e['t'], 'downt': None}
            for h in hyps:
                h[1] = h[1] + [ns]
                h[2] = h[2] + (sig_of(ns),)
            continue
        if ty == 'crash':
            N = e['node']
            for h in hyps:
                S = h[1]; newS = None
                for k, s in enumerate(S):
                    if s['st'] == 'active' and s['node'] == N:
                        if newS is None:
                            newS = list(S)
                        s2 = dict(s)
                        s2['st'] = 'down'; s2['pends'] = s['ends']
                        s2['pos'] = s['dur']; s2['ends'] = (s['dur'],); s2['starts'] = ()
                        s2['epoch'] = s['epoch'] + 1; s2['downt'] = e['t']
                        newS[k] = s2
                if newS is not None:
                    h[1] = newS
                    h[2] = tuple(sig_of(x) for x in newS)
            continue
        if not order:
            continue
        tag = e['sid']
        if tag is not None and tag in sidx:
            cand = [sidx[tag]]
        else:
            cand = range(len(order))
        key = (e['node'], ty, e['off'], e['len'])
        children = []
        for h in hyps:
            S = h[1]
            opts = []
            for k in cand:
                s = S[k]; sid = order[k]
                c = fresh_cost(s, sid, e, p) + P['rec'] * min(max(e['t'] - s['last'], 0), 1000)
                opts.append((c, k, False))
                for (kk, ep, tt) in s['keys']:
                    if kk == key and tt >= e['t'] - P['dupwin']:
                        if ty == 'write':
                            dc = P['dupw'] if ep == s['epoch'] else P['dupx']
                        elif ty in ('commit', 'abort'):
                            dc = 0.0 if s['st'] in ('committed', 'aborted') else 3.0
                        elif ty == 'checkpoint':
                            dc = P['dupw'] if (e['off'] is not None and s['dur'] >= e['off']) else P['dupx']
                        else:
                            dc = P['dupw'] if (s['st'] == 'active' and s['node'] == e['node']) else 3.0
                        opts.append((dc, k, True))
                        break
            opts.sort(key=lambda x: (x[0], x[1], x[2]))
            nopt = P['opts'] if beam_w > 1 else 1
            b0 = opts[0][0]
            for (c, k, dup) in opts[:nopt]:
                if c > b0 + 6.0:
                    break
                children.append((h[0] + c, h, k, dup))
        children.sort(key=lambda x: x[0])
        newh = []
        seen = set()
        for (c, h, k, dup) in children:
            S = h[1]
            if dup:
                sig = h[2]
                ns = None
            else:
                ns = apply(S[k], e)
                sig = h[2][:k] + (sig_of(ns),) + h[2][k + 1:]
            if sig in seen:
                continue
            seen.add(sig)
            if dup:
                newS = S
            else:
                newS = list(S); newS[k] = ns
            newh.append([c, newS, sig, (p, k, dup, h[3])])
            if len(newh) >= beam_w:
                break
        if newh:
            hyps = newh
    best = hyps[0]
    res = {}
    ch = best[3]
    while ch is not None:
        res[ch[0]] = (order[ch[1]], ch[2])
        ch = ch[3]
    for p, e in enumerate(evs):
        if e['type'] == 'open':
            res[p] = (e['sid'], False)
    Sd = {order[k]: best[1][k] for k in range(len(order))}
    return res, Sd, order

def _est_jitter(evs):
    by = {}
    for e in evs:
        if e['sid'] is not None and e['type'] in ('write', 'checkpoint', 'commit') and e['off'] is not None:
            by.setdefault((e['sid'], e['node']), []).append(e)
    gaps = []
    for lst in by.values():
        n = len(lst)
        for a in range(n):
            ea = lst[a]
            for b in range(a + 1, min(n, a + 12)):
                eb = lst[b]
                if eb['t'] - ea['t'] > 30:
                    break
                if eb['type'] == 'write' and eb['off'] < ea['off'] and (eb['off'] + (eb['len'] or 0)) <= ea['off']:
                    gaps.append(eb['t'] - ea['t'])
    if not gaps:
        return 3
    gaps.sort()
    g = gaps[int(0.9 * (len(gaps) - 1))]
    return max(2, min(15, g + 1))

def solve(inp, P=None):
    P0 = _defaults()
    if P:
        P0.update(P)
    P = P0
    evs = list(inp.get('events', []))
    t0 = time.process_time()
    P['JW'] = _est_jitter(evs)
    crash_pos = {}
    for p, e in enumerate(evs):
        if e['type'] == 'crash':
            crash_pos.setdefault(e['node'], []).append(p)
    tagged = {}
    for p, e in enumerate(evs):
        if e['sid'] is not None and e['type'] not in ('open', 'crash'):
            tagged.setdefault(e['sid'], []).append(p)
    prev = None
    res = S = order = None
    bw = P['beam']
    for it in range(3):
        fut = {k: list(v) for k, v in tagged.items()}
        if prev is not None:
            for p, (sid, isdup) in prev.items():
                if isdup:
                    tg = evs[p]['sid']
                    if tg is not None and tg in fut and p in fut[tg]:
                        fut[tg].remove(p)
                    continue
                if evs[p]['sid'] is None and evs[p]['type'] != 'open' and sid is not None:
                    fut.setdefault(sid, []).append(p)
        for k in fut:
            fut[k] = sorted(set(fut[k]))
        el = time.process_time() - t0
        if it > 0 and el > 0.45:
            break
        if el > 0.25:
            bw = 1
        res, S, order = _run(evs, crash_pos, fut, P, bw)
        if prev == res:
            break
        prev = res
    assign = {}
    for p, e in enumerate(evs):
        if e['type'] != 'crash' and e['sid'] is None:
            sid = res.get(p, (None,))[0] if res else None
            if sid is None:
                sid = order[0] if order else ""
            assign[str(e['i'])] = sid
    sessions = {}
    tend = evs[-1]['t'] if evs else 0
    for sid in (order or []):
        s = S[sid]
        st = s['st']
        if st in ('active', 'down'):
            ref = tend if st == 'active' else (s['downt'] if s['downt'] is not None else tend)
            idle = ref - s['last']
            n = s['cnt']
            g = (s['last'] - s['first']) / n if n > 0 else None
            if g is not None and n >= P['MINN'] and idle > P['IK'] * max(g, 1.0) + P['IA']:
                st = 'aborted'
        dur = s['final'] if (st == 'committed' and s['final'] is not None) else s['dur']
        sessions[sid] = {'status': st, 'durable': int(dur)}
    for e in evs:
        if e['type'] == 'open' and e['sid'] is not None and e['sid'] not in sessions:
            sessions[e['sid']] = {'status': 'active', 'durable': 0}
    return {'assignments': assign, 'sessions': sessions}

def run(state, params):
    try:
        state['output'] = solve(state['input'])
    except Exception:
        evs = state.get('input', {}).get('events', [])
        sids = [e['sid'] for e in evs if e.get('type') == 'open' and e.get('sid') is not None]
        first = sids[0] if sids else ""
        assign = {str(e['i']): first for e in evs if e.get('type') != 'crash' and e.get('sid') is None}
        state['output'] = {'assignments': assign,
                           'sessions': {s: {'status': 'active', 'durable': 0} for s in sids}}
    return state

import time
import statistics

CGAP = 2.5
CMISS_CKPT = 1.5
CMISS_REC = 2.5
CREORDER = 0.5
CDUP = 1.0
CBAD = 12.0
CLATE = 0.7
CTWIN = 1.2
KEEP_KEYS = 12
KEEP_BOUNDS = 10

# session tuple fields
ST, NODE, CUR, DUR, GAPS, BOUNDS, LAST, CRT, PREB, KEYS, IR, SID = range(12)


def prepare(state, params):
    inp = state["input"]
    evs = sorted(inp.get("events", []), key=lambda e: (e["t"], e["i"]))
    sids = []
    seen = set()
    for e in evs:
        s = e.get("sid")
        if s is not None and s not in seen:
            seen.add(s)
            sids.append(s)
    bys = {}
    for e in evs:
        if e.get("sid") is not None and e["type"] != "crash":
            bys.setdefault(e["sid"], []).append(e["t"])
    gaps = []
    for s, ts in bys.items():
        for a, b in zip(ts, ts[1:]):
            if b > a:
                gaps.append(b - a)
    msg = statistics.median(gaps) if gaps else 5.0
    state["prep"] = {"sids": sids, "msg": max(1.0, float(msg))}
    return state


def _addkey(keys, k):
    keys = keys + (k,)
    if len(keys) > KEEP_KEYS:
        keys = keys[-KEEP_KEYS:]
    return keys


def _addb(b, *vals):
    b = b + tuple(vals)
    if len(b) > KEEP_BOUNDS:
        b = b[-KEEP_BOUNDS:]
    return b


def _options(s, e, msg, fut=None):
    """List of (cost, new_session_tuple, is_dup) for applying event e to session s."""
    typ = e["type"]
    n = e["node"]
    o = e.get("off")
    ln = e.get("len")
    t = e["t"]
    st = s[ST]
    res = []

    if typ == "open":
        if st != "N":
            return res
        L = list(s)
        L[ST] = "A"
        L[NODE] = n
        L[CUR] = 0
        L[DUR] = 0
        L[GAPS] = ()
        L[BOUNDS] = (0,)
        L[KEYS] = ()
        L[LAST] = t
        L[IR] = None
        res.append((0.0, tuple(L), False))
        return res

    if st == "N":
        return res

    key = (typ, n, o, ln)
    isdupkey = False
    for k in s[KEYS]:
        if k[0] == typ and k[1] == n and k[2] == o and k[3] == ln:
            isdupkey = True
            break
    if isdupkey:
        res.append((CDUP, s, True))

    L = list(s)
    L[LAST] = t
    L[KEYS] = _addkey(s[KEYS], key + (t,))

    def late_cost():
        dt = t - s[CRT]
        return CLATE + 2.0 * max(0.0, dt) / msg

    if typ == "write":
        if o is None or ln is None:
            res.append((1.0, tuple(L), False))
            return res
        end = o + ln
        if st == "A" and s[NODE] == n:
            cur = s[CUR]
            if o == cur:
                L[CUR] = end
                L[BOUNDS] = _addb(s[BOUNDS], end)
                L[IR] = None
                res.append((0.0, tuple(L), False))
            elif o > cur:
                L[CUR] = end
                L[GAPS] = s[GAPS] + ((cur, o),)
                L[BOUNDS] = _addb(s[BOUNDS], o, end)
                res.append((CGAP, tuple(L), False))
            else:
                done = False
                for gi in range(len(s[GAPS])):
                    g0, g1 = s[GAPS][gi]
                    if o >= g0 and end <= g1:
                        ng = list(s[GAPS][:gi]) + list(s[GAPS][gi + 1:])
                        if o > g0:
                            ng.append((g0, o))
                        if end < g1:
                            ng.append((end, g1))
                        if o == g0 and end == g1:
                            c = CREORDER - CGAP + 0.3
                        elif o == g0 or end == g1:
                            c = CREORDER
                        else:
                            c = CREORDER + 1.0
                        L[GAPS] = tuple(ng)
                        L[BOUNDS] = _addb(s[BOUNDS], o, end)
                        res.append((c, tuple(L), False))
                        done = True
                        break
                if not done and not isdupkey:
                    if end in s[BOUNDS] or o in s[BOUNDS]:
                        res.append((3.0, tuple(L), False))
                    else:
                        res.append((CBAD, tuple(L), False))
        elif st == "D":
            if s[NODE] == n:
                c = late_cost() + (0.0 if (o in s[PREB] or end in s[PREB]) else 1.0)
                res.append((c, tuple(L), False))
            dur = s[DUR]
            L2 = list(L)
            L2[ST] = "A"
            L2[NODE] = n
            L2[IR] = n
            if o == dur:
                c = CMISS_REC
            elif o > dur and o in s[PREB]:
                c = CMISS_REC + CMISS_CKPT
                L2[DUR] = o
            elif o > dur:
                c = CMISS_REC + CGAP + 1.0
            else:
                c = CMISS_REC + CBAD
            L2[CUR] = end
            L2[GAPS] = ()
            L2[BOUNDS] = (L2[DUR], o, end)
            res.append((c, tuple(L2), False))
        elif st == "A":
            L[NODE] = n
            L[CUR] = end
            res.append((CBAD + 3.0, tuple(L), False))
        else:
            if not isdupkey:
                if s[NODE] == n and end <= s[CUR] and (end in s[BOUNDS] or o in s[BOUNDS]):
                    res.append((CLATE + 0.5, tuple(L), False))
                else:
                    res.append((CBAD + 3.0, tuple(L), False))
        return res

    if typ in ("checkpoint", "commit"):
        if o is None:
            o = s[CUR]
        fin = "C" if typ == "commit" else None
        if st == "A" and s[NODE] == n:
            cur = s[CUR]
            if o == cur:
                L[DUR] = o
                if fin:
                    L[ST] = fin
                L[IR] = None
                res.append((0.0, tuple(L), False))
            elif o > cur:
                L[CUR] = o
                L[DUR] = o
                L[GAPS] = s[GAPS] + ((cur, o),)
                L[BOUNDS] = _addb(s[BOUNDS], o)
                if fin:
                    L[ST] = fin
                res.append((CGAP, tuple(L), False))
            else:
                if not isdupkey:
                    if o in s[BOUNDS] and o >= s[DUR]:
                        L[DUR] = o
                        c = CREORDER
                        if fin:
                            L[ST] = fin
                            L[CUR] = o
                            c = CREORDER + 2.0
                        res.append((c, tuple(L), False))
                    else:
                        L[DUR] = max(s[DUR], o)
                        if fin:
                            L[ST] = fin
                            L[CUR] = o
                            L[DUR] = o
                        res.append((CBAD, tuple(L), False))
        elif st == "D":
            if s[NODE] == n:
                c = late_cost() + (0.0 if (o in s[PREB] or o >= s[DUR]) else 2.0)
                L[DUR] = max(s[DUR], o)
                L[CUR] = L[DUR]
                if fin:
                    L[ST] = fin
                    L[DUR] = o
                    L[CUR] = o
                res.append((c, tuple(L), False))
            L2 = list(L)
            L2[ST] = fin or "A"
            L2[NODE] = n
            L2[IR] = n
            dur = s[DUR]
            if o == dur:
                c = CMISS_REC
            elif o > dur:
                c = CMISS_REC + CGAP
            else:
                c = CMISS_REC + CBAD
            L2[CUR] = o
            L2[DUR] = o
            L2[GAPS] = ()
            L2[BOUNDS] = (o,)
            res.append((c, tuple(L2), False))
        elif st == "A":
            L[NODE] = n
            L[CUR] = o
            L[DUR] = o
            if fin:
                L[ST] = fin
            res.append((CBAD + 3.0, tuple(L), False))
        else:
            if not isdupkey:
                if typ == "checkpoint" and s[NODE] == n and o in s[BOUNDS] and o <= s[CUR]:
                    res.append((CLATE + 0.5, tuple(L), False))
                else:
                    res.append((CBAD + 3.0, tuple(L), False))
        return res

    if typ == "abort":
        if st == "A" and s[NODE] == n:
            L[ST] = "X"
            c = 0.2
            if fut is not None:
                if s[CUR] in fut[0]:
                    c += 2.5
                if s[SID] in fut[1]:
                    c += 6.0
            res.append((c, tuple(L), False))
        elif st == "D":
            if s[NODE] == n:
                L[ST] = "X"
                res.append((late_cost(), tuple(L), False))
            L2 = list(L)
            L2[ST] = "X"
            L2[NODE] = n
            res.append((CMISS_REC + 0.5, tuple(L2), False))
        elif st == "A":
            L[ST] = "X"
            L[NODE] = n
            res.append((CBAD + 3.0, tuple(L), False))
        else:
            if not isdupkey:
                res.append((CBAD + 3.0, tuple(L), False))
        return res

    if typ == "recover":
        if o is None:
            o = s[DUR]
        if st == "D":
            dur = s[DUR]
            if o == dur:
                c = 0.0
            elif o > dur and o in s[PREB]:
                c = CMISS_CKPT
            elif o > dur:
                c = CMISS_CKPT + CGAP
            else:
                c = 6.0
            L[ST] = "A"
            L[NODE] = n
            L[CUR] = o
            L[DUR] = o
            L[GAPS] = ()
            L[BOUNDS] = (o,)
            L[IR] = None
            res.append((c, tuple(L), False))
        elif st == "A":
            if s[IR] == n and o == s[DUR]:
                L[IR] = None
                res.append((-(CMISS_REC - 0.5), tuple(L), False))
            elif not isdupkey:
                L[NODE] = n
                L[CUR] = o
                L[DUR] = o
                L[GAPS] = ()
                L[BOUNDS] = (o,)
                res.append((CBAD + 2.0, tuple(L), False))
        else:
            if not isdupkey:
                res.append((CBAD + 4.0, tuple(L), False))
        return res

    res.append((CBAD, tuple(L), False))
    return res


def beam_search(state, params):
    t0 = time.process_time()
    inp = state["input"]
    prep = state["prep"]
    sids = prep["sids"]
    msg = prep["msg"]
    sidx = {}
    for k, s in enumerate(sids):
        sidx[s] = k
    evs = sorted(inp.get("events", []), key=lambda e: (e["t"], e["i"]))
    nev = len(evs)

    twins = {}
    bykey = {}
    for e in evs:
        if e["type"] in ("crash", "open"):
            continue
        k = (e["type"], e["node"], e.get("off"), e.get("len"))
        bykey.setdefault(k, []).append(e)
    for k, lst in bykey.items():
        if len(lst) < 2:
            continue
        known = set(x["sid"] for x in lst if x.get("sid") is not None)
        if not known:
            continue
        for x in lst:
            if x.get("sid") is None:
                twins[x["i"]] = known

    init = tuple(("N", None, 0, 0, (), (), 0, 0, (), (), None, sd) for sd in sids)
    beam = [(0.0, init, None)]
    width = 24
    budget = 0.6
    for ei in range(nev):
        e = evs[ei]
        if ei % 10 == 0 and ei > 0:
            el = time.process_time() - t0
            if el > 1.0:
                width = 1
            else:
                per = el / ei
                remain = nev - ei
                if per * remain > (budget - el):
                    width = max(2, int(width * 0.6))
                elif per * remain < 0.35 * (budget - el) and width < 48:
                    width = width + 4
        typ = e["type"]
        if typ == "crash":
            nb = []
            n = e["node"]
            for cost, ss, link in beam:
                L = list(ss)
                for k in range(len(ss)):
                    s = ss[k]
                    if s[ST] == "A" and s[NODE] == n:
                        x = list(s)
                        x[ST] = "D"
                        x[CRT] = e["t"]
                        x[PREB] = s[BOUNDS]
                        x[CUR] = s[DUR]
                        x[GAPS] = ()
                        x[BOUNDS] = (s[DUR],)
                        x[IR] = None
                        L[k] = tuple(x)
                nb.append((cost, tuple(L), link))
            beam = nb
            continue
        sid = e.get("sid")
        if sid is not None and sid in sidx:
            cands = [sidx[sid]]
            anon = False
        else:
            cands = list(range(len(sids)))
            anon = True
        if not cands:
            continue
        tw = twins.get(e["i"]) if anon else None
        fut = None
        if typ == "abort":
            fo = set()
            fs = set()
            hz = e["t"] + 8.0 * msg
            for f in evs[ei + 1:]:
                if f["type"] in ("crash", "abort"):
                    continue
                if f.get("sid") is not None:
                    if f["t"] > e["t"] + 0.5 * msg:
                        fs.add(f["sid"])
                elif f["t"] <= hz and f["node"] == e["node"] and f["type"] in ("write", "checkpoint", "commit"):
                    fo.add(f.get("off"))
            fut = (fo, fs)
        nb = []
        for cost, ss, link in beam:
            local = []
            for k in cands:
                for c, ns, isdup in _options(ss[k], e, msg, fut):
                    if tw and sids[k] in tw:
                        c -= CTWIN
                    local.append((cost + c, k, ns))
            if not local:
                if anon:
                    nb.append((cost + CBAD * 2, ss, (e["i"], 0, link)))
                else:
                    nb.append((cost, ss, link))
                continue
            local.sort(key=lambda x: x[0])
            for c, k, ns in local[:6]:
                L = list(ss)
                L[k] = ns
                nl = (e["i"], k, link) if anon else link
                nb.append((c, tuple(L), nl))
        nb.sort(key=lambda x: x[0])
        out = []
        seen = set()
        for item in nb:
            sg = tuple((s[ST], s[NODE], s[CUR], s[DUR], s[GAPS]) for s in item[1])
            if sg in seen:
                continue
            seen.add(sg)
            out.append(item)
            if len(out) >= width:
                break
        beam = out

    best = beam[0]
    assign = {}
    link = best[2]
    while link is not None:
        i, k, link = link
        if sids:
            assign[str(i)] = sids[k]
    stmap = {"A": "active", "D": "down", "C": "committed", "X": "aborted", "N": "active"}
    sessions = {}
    for k in range(len(sids)):
        s = best[1][k]
        sessions[sids[k]] = {"status": stmap.get(s[ST], "active"), "durable": int(s[DUR])}
    for e in evs:
        if e["type"] != "crash" and e.get("sid") is None and str(e["i"]) not in assign:
            assign[str(e["i"])] = sids[0] if sids else ""
    state["output"] = {"assignments": assign, "sessions": sessions}
    return state


def solve(state, params):
    try:
        state = prepare(state, params)
        state = beam_search(state, params)
    except Exception:
        inp = state.get("input", {})
        evs = inp.get("events", [])
        sids = []
        for e in evs:
            if e.get("sid") is not None and e["sid"] not in sids:
                sids.append(e["sid"])
        assign = {}
        for e in evs:
            if e.get("type") != "crash" and e.get("sid") is None:
                assign[str(e["i"])] = sids[0] if sids else ""
        state["output"] = {"assignments": assign,
                           "sessions": {s: {"status": "active", "durable": 0} for s in sids}}
    return state

import time


def solve(state, params):
    inp = state["input"]
    evs = sorted(inp["events"], key=lambda e: (e["t"], e["i"]))
    n = len(evs)
    sids = []
    for e in evs:
        if e["type"] == "open" and e["sid"] and e["sid"] not in sids:
            sids.append(e["sid"])
    for e in evs:
        if e["sid"] and e["type"] != "crash" and e["sid"] not in sids:
            sids.append(e["sid"])
    sidx = {s: k for k, s in enumerate(sids)}
    S = len(sids)
    ts = [e["t"] for e in evs]
    gaps = sorted(ts[k + 1] - ts[k] for k in range(n - 1)) or [1]
    med = max(1.0, float(gaps[len(gaps) // 2]))
    W = 12.0 * med
    # duplicate original candidates
    dupc = [[] for _ in range(n)]
    for k in range(n):
        e = evs[k]
        if e["type"] in ("open", "crash"):
            continue
        for j in range(k - 1, -1, -1):
            if ts[k] - ts[j] > 40 * med:
                break
            f = evs[j]
            if f["type"] == e["type"] and f["node"] == e["node"] and f["off"] == e["off"] and f["len"] == e["len"]:
                if e["sid"] and f["sid"] and e["sid"] != f["sid"]:
                    continue
                dupc[k].append(j)
    isorig = [False] * n
    for k in range(n):
        for j in dupc[k]:
            isorig[j] = True
    # session tuple: (st, node, cur, dur, holes, pc, last_t, opent)
    # st: 0 unopened 1 active 2 down 3 committed 4 aborted
    init = tuple((0, None, 0, 0, (), 0, 0, 0) for _ in range(S))

    def fill(holes, o, L, t):
        for h in holes:
            a, b, ht = h
            if a <= o and o + L <= b and t - ht <= 4 * W:
                nh = [x for x in holes if x is not h]
                if a < o:
                    nh.append((a, o, ht))
                if o + L < b:
                    nh.append((o + L, b, ht))
                return tuple(nh), 1.0 + (t - ht) / W
        return None, 0

    def addhole(holes, a, b, t):
        nh = [h for h in holes if t - h[2] <= 4 * W]
        nh.append((a, b, t))
        if len(nh) > 6:
            nh = nh[-6:]
        return tuple(nh)

    def options(sess, e, t, k):
        st, node, cur, dur, holes, pc, lt, ot = sess
        ty = e["type"]
        o = e["off"]
        nd = e["node"]
        res = []
        if st == 0:
            return res
        if ty == "write":
            if o is None:
                return res
            L = e["len"] or 0
            if st == 1 and node == nd:
                if o == cur:
                    res.append((0.0, (1, node, o + L, dur, holes, pc, t, ot)))
                elif o > cur:
                    res.append((3.0, (1, node, o + L, dur, addhole(holes, cur, o, t), pc, t, ot)))
            if node == nd and st in (1, 3, 4):
                nh, c = fill(holes, o, L, t)
                if nh is not None:
                    res.append((c, (st, node, cur, dur, nh, pc, t, ot)))
            if st == 2:
                if node == nd and o >= pc and t - lt <= 4 * W:
                    res.append((1.0 + 2.0 * (o > pc), (2, node, cur, dur, holes, o + L, lt, ot)))
                if o >= dur:
                    res.append((4.0 + 2.0 * (o > dur), (1, nd, o + L, o, (), 0, t, ot)))
        elif ty in ("checkpoint", "commit"):
            if o is None:
                return res
            nst = 1 if ty == "checkpoint" else 3
            if st == 1 and node == nd:
                if o == cur:
                    res.append((0.0, (nst, node, o, o, holes, pc, t, ot)))
                elif o > cur:
                    res.append((3.0, (nst, node, o, o, addhole(holes, cur, o, t), pc, t, ot)))
                elif o >= dur and t - lt <= 4 * W:
                    res.append((1.5, (nst, node, cur if nst == 1 else o, o, holes, pc, t, ot)))
            if st == 2 and node == nd and dur <= o <= pc and t - lt <= 4 * W:
                res.append((1.5, (2, node, o, o, holes, o, lt, ot)))
            if st == 2 and o >= dur:
                res.append((5.0, (nst, nd, o, o, (), 0, t, ot)))
        elif ty == "abort":
            if st == 1 and node == nd:
                res.append((0.3, (4, node, cur, dur, holes, pc, t, ot)))
            elif st == 2:
                res.append((5.0, (4, node, dur, dur, holes, pc, t, ot)))
        elif ty == "recover":
            if o is None:
                o = dur
            if st == 2:
                if o == dur:
                    c = 0.0
                elif o > dur:
                    c = 2.0
                else:
                    c = 6.0
                res.append((c, (1, nd, o, o, (), 0, t, ot)))
            elif st == 1 and o == dur and t - lt <= 4 * W:
                res.append((5.0, (1, nd, o, o, (), 0, t, ot)))
        return res

    beam = [(0.0, init, None)]
    B = 40 if n <= 200 else (24 if n <= 400 else 16)
    t0 = time.process_time()

    def lookup(h, j, limit):
        steps = 0
        while h is not None and steps < limit:
            if h[1] == j:
                return h[2]
            if h[1] < j:
                return None
            h = h[0]
            steps += 1
        return None

    for k in range(n):
        if time.process_time() - t0 > 0.75:
            B = 3
        e = evs[k]
        t = ts[k]
        ty = e["type"]
        cand = []
        if ty == "crash":
            for c, ss, h in beam:
                nl = list(ss)
                ch = False
                for q in range(S):
                    s = ss[q]
                    if s[0] == 1 and s[1] == e["node"]:
                        nl[q] = (2, s[1], s[3], s[3], (), s[2], t, s[7])
                        ch = True
                cand.append((c, tuple(nl) if ch else ss, h))
        elif ty == "open" and e["sid"] in sidx:
            q = sidx[e["sid"]]
            for c, ss, h in beam:
                s = ss[q]
                if s[0] == 0:
                    nl = list(ss)
                    nl[q] = (1, e["node"], 0, 0, (), 0, t, t)
                    cand.append((c, tuple(nl), (h, k, q)))
                else:
                    cand.append((c + 2.0, ss, (h, k, q)))
        else:
            known = sidx.get(e["sid"]) if e["sid"] else None
            for c, ss, h in beam:
                got = False
                qs = range(S) if known is None else (known,)
                for q in qs:
                    for oc, ns in options(ss[q], e, t, k):
                        nl = list(ss)
                        nl[q] = ns
                        cand.append((c + oc, tuple(nl), (h, k, q)))
                        got = True
                for j in dupc[k]:
                    q = lookup(h, j, 400)
                    if q is None or (known is not None and q != known):
                        continue
                    cand.append((c + 1.5 + (t - ts[j]) / (20 * W), ss, (h, k, q)))
                    got = True
                if not got:
                    if known is not None:
                        cand.append((c + 10.0, ss, (h, k, known)))
                    else:
                        best = None
                        for q in range(S):
                            s = ss[q]
                            if s[0] == 0:
                                continue
                            d = 0.0 if s[1] == e["node"] else 1.0
                            d += 0.5 * (s[0] != 1) + abs(t - s[6]) / (50.0 * W)
                            if e["off"] is not None:
                                d += abs(e["off"] - s[2]) / 1e6
                            if best is None or d < best[0]:
                                best = (d, q)
                        if best is None:
                            best = (0, 0)
                        cand.append((c + 10.0 + best[0], ss, (h, k, best[1])))
        if not cand:
            continue
        cand.sort(key=lambda x: x[0])
        nb = []
        seen = set()
        near_orig = isorig[k] or any(isorig[j] for j in range(max(0, k - 3), k))
        for x in cand:
            key = x[1]
            if near_orig:
                key = (x[1], x[2][2] if x[2] is not None and x[2][1] == k else -1)
            if key in seen:
                continue
            seen.add(key)
            nb.append(x)
            if len(nb) >= B:
                break
        beam = nb
    c, ss, h = beam[0]
    asg = {}
    while h is not None:
        asg[h[1]] = h[2]
        h = h[0]
    assignments = {}
    for k in range(n):
        e = evs[k]
        if e["type"] != "crash" and not e["sid"]:
            q = asg.get(k, 0)
            assignments[str(e["i"])] = sids[q] if S else ""
    sessions = {}
    names = {0: "active", 1: "active", 2: "down", 3: "committed", 4: "aborted"}
    for q in range(S):
        s = ss[q]
        sessions[sids[q]] = {"status": names[s[0]], "durable": int(s[3])}
    state["output"] = {"assignments": assignments, "sessions": sessions}
    return state

import bisect
import statistics
import time

INF = 10 ** 9


def prepare(state, params):
    inp = state.get("input") or {}
    evs = sorted(inp.get("events", []) or [], key=lambda e: (e.get("t", 0), e.get("i", 0)))
    sids = []
    seen = set()
    for e in evs:
        if e.get("type") == "open" and e.get("sid") is not None and e["sid"] not in seen:
            seen.add(e["sid"])
            sids.append(e["sid"])
    for e in evs:
        s = e.get("sid")
        if s is not None and e.get("type") != "crash" and s not in seen:
            seen.add(s)
            sids.append(s)
    ts = [e.get("t", 0) for e in evs]
    gaps = [ts[k + 1] - ts[k] for k in range(len(ts) - 1)]
    mg = statistics.median(gaps) if gaps else 1
    mg = max(mg, 1)
    inv = 0
    byk = {}
    for p, e in enumerate(evs):
        if e.get("sid") is not None and e.get("type") in ("write", "checkpoint", "commit") and e.get("off") is not None:
            byk.setdefault(e["sid"], []).append(p)
    for s, ps in byk.items():
        for a in range(len(ps)):
            ea = evs[ps[a]]
            for b in range(a + 1, min(len(ps), a + 6)):
                eb = evs[ps[b]]
                if eb.get("type") == "write" and eb.get("len") is not None:
                    if eb["off"] + eb["len"] == ea["off"] and eb["node"] == ea["node"]:
                        inv = max(inv, eb["t"] - ea["t"])
    W = max(inv * 1.5 + 1, 3 * mg)
    state["prep"] = {"events": evs, "sids": sids, "W": W}
    return state


def _simulate(evs, sids, W, assign_hint):
    crash_pos = {}
    for p, e in enumerate(evs):
        if e["type"] == "crash":
            crash_pos.setdefault(e["node"], []).append(p)
    seq = {s: [] for s in sids}
    for p, e in enumerate(evs):
        if e["type"] in ("crash", "open"):
            continue
        s = e.get("sid")
        w = 1.0
        if s is None:
            s = assign_hint.get(p)
            w = 0.5
        if s is not None and s in seq:
            seq[s].append((p, w))
    seqp = {s: [x[0] for x in v] for s, v in seq.items()}

    def crash_between(node, p1, p2):
        lst = crash_pos.get(node)
        if not lst:
            return False
        k = bisect.bisect_right(lst, p1)
        return k < len(lst) and lst[k] < p2

    def nextev(s, p):
        ps = seqp[s]
        k = bisect.bisect_right(ps, p)
        if k < len(ps):
            return evs[ps[k]], seq[s][k][1], ps[k]
        return None, 0, None

    S = {}
    for s in sids:
        S[s] = {"st": "pending", "node": None, "cur": 0, "dur": 0, "E": {0}, "ct": -INF,
                "pre": 0, "last": None, "H": set(), "fin": None, "endt": None, "act_t": -INF}

    def lookahead(s, p, e):
        k, w, pk = nextev(s, p)
        if k is None:
            return 0.0
        typ = e["type"]
        N = e["node"]
        cb = crash_between(N, p, pk)
        dt = k["t"] - e["t"]
        pen = 0.0
        if typ in ("write", "checkpoint", "commit"):
            if e["off"] is None:
                return 0.0
            end = e["off"] + (e["len"] or 0)
            if typ == "commit":
                if not (k["type"] == "commit" and k["off"] == e["off"]) and dt > W:
                    pen += 6
                return pen * w
            if k["type"] in ("write", "checkpoint", "commit") and k["node"] == N and not cb and k["off"] is not None:
                Y = k["off"]
                if Y == end:
                    pen -= 1.5
                elif Y > end:
                    pen += 0.0
                elif dt <= W:
                    pen += 0.5
                else:
                    pen += 4
            elif k["type"] == "recover":
                if not cb and dt > W:
                    pen += 3
            elif k["node"] != N and not cb and dt > W:
                pen += 3
        elif typ == "recover":
            if k["type"] in ("write", "checkpoint", "commit", "abort"):
                if k["node"] == N:
                    pen -= 1
                    if k["type"] == "write" and k["off"] == e["off"]:
                        pen -= 1
                elif dt > W:
                    pen += 3
            elif k["type"] == "recover":
                if not (k["off"] == e["off"] and k["node"] == N) and not cb:
                    pen += 2
        elif typ == "abort":
            if k["type"] != "abort" and dt > W:
                pen += 6
        return pen * w

    def key_of(e):
        return (e["type"], e["node"], e["off"], e["len"])

    def is_dup(s, e):
        return key_of(e) in S[s]["H"]

    def straggler(d, N, t):
        return d["node"] == N and t - d["ct"] <= W

    def base_cost(s, e):
        d = S[s]
        st = d["st"]
        typ = e["type"]
        N = e["node"]
        t = e["t"]
        X = e["off"]
        L = e["len"] or 0
        if st == "pending":
            return INF
        if typ == "write" or typ == "checkpoint":
            if X is None:
                X = d["cur"]
            if st == "active":
                if d["node"] != N:
                    return INF
                if X == d["cur"]:
                    return 0.0
                if X in d["E"]:
                    return 2.0
                if X > d["cur"]:
                    return 3.0 + (X - d["cur"]) * 1e-9
                return 8.0
            if st == "down":
                if straggler(d, N, t):
                    if X == d["pre"] or X in d["E"]:
                        return 1.0
                    if X > d["pre"]:
                        return 4.0
                    return 7.0
                if X == d["dur"]:
                    return 3.0
                if X > d["dur"]:
                    return 4.5
                return 9.0
            if d["endt"] is not None and t - d["endt"] <= W and d["node"] == N:
                if X in d["E"] or (d["fin"] is not None and X + L <= d["fin"]):
                    return 2.0
            return INF
        if typ == "commit":
            if X is None:
                X = d["cur"]
            if st == "active":
                if d["node"] != N:
                    return INF
                if X == d["cur"]:
                    return 0.0
                if X in d["E"]:
                    return 2.0
                if X > d["cur"]:
                    return 3.0
                return 8.0
            if st == "down":
                if straggler(d, N, t):
                    if X == d["pre"] or X in d["E"]:
                        return 1.0
                    if X > d["pre"]:
                        return 4.0
                    return 7.0
                if X == d["dur"]:
                    return 4.0
                if X > d["dur"]:
                    return 5.0
                return INF
            return INF
        if typ == "abort":
            if st == "active":
                if d["node"] != N:
                    return INF
                return 1.0
            if st == "down":
                if straggler(d, N, t):
                    return 1.5
                return 5.0
            return INF
        if typ == "recover":
            if st == "down":
                if X is None:
                    return 1.0
                if X == d["dur"]:
                    return 0.0
                if X > d["dur"]:
                    return 2.0
                return 6.0
            if st == "active" and X is not None:
                # recover arriving after an implicitly inferred recovery (jitter / reorder)
                if d["node"] == N and t - d["act_t"] <= W and X <= d["cur"]:
                    return 1.5
                if t - d["ct"] <= W and X == d["dur"]:
                    return 5.0
            return INF
        return INF

    def apply(s, e):
        d = S[s]
        typ = e["type"]
        N = e["node"]
        t = e["t"]
        X = e["off"]
        L = e["len"] or 0
        d["H"].add(key_of(e))
        d["last"] = t
        st = d["st"]
        if typ == "open":
            d["st"] = "active"
            d["node"] = N
            d["cur"] = 0
            d["dur"] = 0
            return
        if typ == "write":
            if X is None:
                return
            if st == "active":
                d["node"] = N
                if X + L > d["cur"]:
                    d["cur"] = X + L
            elif st == "down":
                if straggler(d, N, t) and (X == d["pre"] or X in d["E"] or X > d["pre"]):
                    if X + L > d["pre"]:
                        d["pre"] = X + L
                else:
                    d["st"] = "active"
                    d["node"] = N
                    d["act_t"] = t
                    if X > d["dur"]:
                        d["dur"] = X
                    d["cur"] = X + L
            d["E"].add(X)
            d["E"].add(X + L)
        elif typ == "checkpoint":
            if X is None:
                return
            if st == "active":
                d["node"] = N
                if X > d["dur"]:
                    d["dur"] = X
                if X > d["cur"]:
                    d["cur"] = X
            elif st == "down":
                if straggler(d, N, t):
                    if X > d["dur"]:
                        d["dur"] = X
                    if X > d["pre"]:
                        d["pre"] = X
                    d["cur"] = d["dur"]
                else:
                    d["st"] = "active"
                    d["node"] = N
                    d["act_t"] = t
                    if X > d["dur"]:
                        d["dur"] = X
                    d["cur"] = X
            d["E"].add(X)
        elif typ == "commit":
            if X is not None:
                d["E"].add(X)
                d["fin"] = X
                d["dur"] = X
            d["st"] = "committed"
            d["endt"] = t
            d["node"] = N
        elif typ == "abort":
            d["st"] = "aborted"
            d["endt"] = t
            d["cur"] = d["dur"]
        elif typ == "recover":
            if st == "active" and d["node"] == N and t - d["act_t"] <= W and X is not None and X <= d["cur"]:
                d["dur"] = X
                return
            d["st"] = "active"
            d["node"] = N
            if X is not None:
                d["dur"] = X
                d["cur"] = X
                d["E"].add(X)

    def dup_ok(s, e):
        d = S[s]
        if not is_dup(s, e):
            return False
        typ = e["type"]
        if typ == "write":
            return not (d["st"] == "active" and d["node"] == e["node"] and e["off"] == d["cur"])
        if typ == "checkpoint":
            return True
        if typ in ("commit", "abort"):
            return d["st"] in ("committed", "aborted")
        if typ == "recover":
            return d["st"] != "down"
        return False

    result = {}
    for p, e in enumerate(evs):
        typ = e["type"]
        if typ == "crash":
            for s in sids:
                d = S[s]
                if d["st"] == "active" and d["node"] == e["node"]:
                    d["st"] = "down"
                    d["ct"] = e["t"]
                    d["pre"] = d["cur"]
                    d["cur"] = d["dur"]
            continue
        s = e.get("sid")
        if typ == "open":
            if s is not None and s in S:
                apply(s, e)
            continue
        if s is not None and s in S:
            if S[s]["st"] == "pending":
                S[s]["st"] = "active"
                S[s]["node"] = e["node"]
            if dup_ok(s, e):
                continue
            apply(s, e)
            continue
        best = None
        bc = INF
        bdup = False
        for c in sids:
            if S[c]["st"] == "pending":
                continue
            cost = base_cost(c, e)
            dup = False
            if is_dup(c, e) and 0.3 < cost and dup_ok(c, e):
                cost = 0.3
                dup = True
            if cost >= INF:
                continue
            cost += lookahead(c, p, e)
            lt = S[c]["last"]
            if lt is not None:
                cost += min(max(e["t"] - lt, 0), 10 ** 6) * 1e-9
            if cost < bc:
                bc = cost
                best = c
                bdup = dup
        if best is None:
            cands = [c for c in sids if S[c]["st"] != "pending"]
            same = [c for c in cands if S[c]["node"] == e["node"]]
            pool = same or cands or list(sids)
            if not pool:
                continue
            best = pool[0]
            bdup = True
        result[p] = best
        if not bdup:
            apply(best, e)
    return result, S


def _fallback(state):
    inp = state.get("input") or {}
    evs = inp.get("events", []) or []
    sids = []
    for e in evs:
        if e.get("sid") is not None and e.get("type") != "crash" and e["sid"] not in sids:
            sids.append(e["sid"])
    node_of = {}
    for e in evs:
        if e.get("type") == "open" and e.get("sid") is not None:
            node_of[e["sid"]] = e.get("node")
    assignments = {}
    for e in evs:
        if e.get("sid") is None and e.get("type") != "crash":
            c = [s for s in sids if node_of.get(s) == e.get("node")]
            assignments[str(e.get("i"))] = (c or sids or [""])[0]
    sessions = {s: {"status": "active", "durable": 0} for s in sids}
    return {"assignments": assignments, "sessions": sessions}


def solve(state, params):
    try:
        prep = state["prep"]
        evs = prep["events"]
        sids = prep["sids"]
        W = prep["W"]
        start = time.process_time()
        result, S = _simulate(evs, sids, W, {})
        for it in range(3):
            if time.process_time() - start > 0.4:
                break
            r2, S2 = _simulate(evs, sids, W, result)
            same = (r2 == result)
            result, S = r2, S2
            if same:
                break
        assignments = {}
        for p, s in result.items():
            e = evs[p]
            if e.get("sid") is None and e["type"] != "crash":
                assignments[str(e["i"])] = s
        for e in evs:
            if e.get("sid") is None and e["type"] != "crash" and str(e["i"]) not in assignments:
                assignments[str(e["i"])] = sids[0] if sids else ""
        sessions = {}
        for s in sids:
            d = S[s]
            st = d["st"]
            if st == "pending":
                st = "active"
            dur = d["dur"]
            if st == "committed" and d["fin"] is not None:
                dur = d["fin"]
            sessions[s] = {"status": st, "durable": int(dur)}
        state["output"] = {"assignments": assignments, "sessions": sessions}
    except Exception:
        state["output"] = _fallback(state)
    state.pop("prep", None)
    return state
